-- Migration 064: Informatics 9th grade - the course "Informatics 9th grade" with the 8 lessons of textbook Chapter 2 "Databases" (sheet and SQL side by side)
-- Needs 041_sheet_criteria.sql. Idempotent: the course is found by title, the module by title, lessons by module position (or title).

do $informatics9$
declare
  v_school uuid; v_owner uuid; v_course uuid; v_module uuid; v_lesson uuid; v_spec record;
begin
  -- the course belongs to the teacher who owns the 8th-grade course (so it shows in that teacher's library)
  select c.owner_id, c.school_id into v_owner, v_school from public.cf_curr_courses c
  where c.title in ('Informatics 8th grade', 'Информатика 8-сынып', 'Информатика 8') order by c.created_at limit 1;
  if v_owner is null then select p.id, p.school_id into v_owner, v_school from public.profiles p where p.role in ('teacher', 'admin') order by p.created_at limit 1; end if;
  if v_owner is null then raise exception 'Мұғалім немесе әкімші аккаунты табылмады'; end if;

  select id into v_course from public.cf_curr_courses where title = $s9$Informatics 9th grade$s9$ and school_id = v_school limit 1;
  if v_course is null then
    insert into public.cf_curr_courses (school_id, owner_id, title, subject, grade)
    values (v_school, v_owner, $s9$Informatics 9th grade$s9$, $s9$Информатика$s9$, 9) returning id into v_course;
  end if;

  select id into v_module from public.cf_curr_modules where course_id = v_course and title = $s9$Деректер қоры (2-тарау)$s9$ limit 1;
  if v_module is null then
    insert into public.cf_curr_modules (course_id, title, position, kind, quarter, grade)
    values (v_course, $s9$Деректер қоры (2-тарау)$s9$, 1, 'lesson', 2, 9) returning id into v_module;
  end if;

  for v_spec in select * from (values
    ($s9$2.1 Деректер қоры деген не?$s9$, $s9$Информатика$s9$, 0, $s9${"summary":"Деректер қоры — реттелген деректер жиыны. Кесте, жазба, өріс. ДҚБЖ және SQL: SELECT сұранысымен кестені көру.","objectives":["Деректер қорының мағынасы мен қолданылуын түсіндіру","Кесте, жазба (record) және өрісті (field) ажырату","SELECT сұранысымен кестенің барлық немесе таңдалған өрістерін шығару"],"grade":9,"duration":"45 минут","prior":"Электрондық кестеде жол, баған, ұяшықты біледі; SUM функциясын қолдана алады (8-сынып).","env":"ClassFlow кестесі және ClassFlow SQL редакторы (браузерде, орнату керек емес). Әр оқушыға бір құрылғы және интернет қажет. Google аккаунты керек емес.","source":"Информатика, 9-сынып оқулығы, 2-тарау, 24–25 беттер. Сабақ оқулықтан әдейі ауытқиды: Google Forms орнына әр тақырып кестеде және SQL-де қатар орындалады. Барлық сұраныстар мен жауаптар орындалып тексерілген, деректер оқу үшін құрастырылған.","stages":[{"k":"warmup","min":5,"do":"Электрондық кесте туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Деректер қоры, жазба, өріс және ДҚБЖ ұғымдарын үйренеді"},{"k":"example","min":10,"do":"Кітапхана кестесін кестеде қарап, SELECT сұранысын мұғаліммен бірге орындайды"},{"k":"practice","min":15,"do":"Екі SELECT сұранысын өзі жазады; үлгерген оқушы ★ сұранысты орындайды"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"База данных — упорядоченный набор данных. Таблица, запись, поле. СУБД и SQL: просмотр таблицы запросом SELECT.","objectives":["Объяснять, что такое база данных и зачем она нужна","Различать таблицу, запись (record) и поле (field)","Выводить все или выбранные поля таблицы запросом SELECT"],"prior":"Знают строку, столбец и ячейку электронной таблицы; умеют применять SUM (8 класс).","env":"Таблица ClassFlow и SQL-редактор ClassFlow (в браузере, устанавливать ничего не нужно). Каждому ученику нужны устройство и интернет. Аккаунт Google не нужен.","source":"Информатика, учебник 9 класса, глава 2, с. 24–25. Урок намеренно отходит от учебника: вместо Google Forms каждая тема выполняется параллельно в таблице и в SQL. Все запросы и ответы проверены выполнением, данные учебные.","stages":["Отвечает на два вопроса об электронных таблицах","Изучает понятия база данных, запись, поле и СУБД","Рассматривает таблицу библиотеки и вместе с учителем выполняет SELECT","Сам пишет два запроса SELECT; кто успел — запрос ★","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"A database is an organised collection of data. Table, record, field. DBMS and SQL: viewing a table with SELECT.","objectives":["Explain what a database is and what it is for","Tell a table, a record and a field apart","Show all or chosen fields of a table with SELECT"],"prior":"Know rows, columns and cells of a spreadsheet; can use SUM (Grade 8).","env":"The ClassFlow sheet and the ClassFlow SQL editor (in the browser, nothing to install). One device per student and the internet. No Google account is needed.","source":"Informatics, Grade 9 textbook, chapter 2, pp. 24–25. The lesson leaves the textbook on purpose: instead of Google Forms every topic is done side by side in a sheet and in SQL. Every query and answer was run; the data are made for the classroom.","stages":["Answers two questions about spreadsheets","Learns database, record, field and DBMS","Looks at the library table and runs SELECT with the teacher","Writes two SELECT queries alone; fast students take the ★ query","Takes a short test and says what was learned"]}}$s9$::jsonb, $s9$[{"term":"database","definition":"Деректер қоры — реттеліп сақталған деректер жиыны · База данных — упорядоченно хранимый набор данных · Database — an organised collection of data"},{"term":"record","definition":"Жазба — бір нысан туралы мәлімет, кестенің бір жолы · Запись — сведения об одном объекте, одна строка таблицы · Record — the information about one item, one row of a table"},{"term":"field","definition":"Өріс — бір түрдегі мәлімет сақталатын баған · Поле — столбец с данными одного вида · Field — a column that stores one kind of information"},{"term":"DBMS","definition":"ДҚБЖ — деректер қорын басқаратын және қорғайтын бағдарлама · СУБД — программа для управления базой данных и её защиты · DBMS — the program that manages and protects a database"},{"term":"query","definition":"Сұраныс — деректер қорына қойылатын сұрақ: табу, сұрыптау, есептеу · Запрос — вопрос к базе данных: найти, отсортировать, посчитать · Query — a question to a database: find, sort, calculate"}]$s9$::jsonb, $s9$[{"type":"title","pageType":"slide","templateId":"title","title":"2.1 Деректер қоры деген не?","subtitle":"Информатика 9-сынып · 2-тарау «Деректер қоры» · оқулық 24–25-б.","ru":{"title":"2.1 Что такое база данных?","subtitle":"Информатика 9 класс · глава 2 «Базы данных» · учебник, с. 24–25"},"en":{"title":"2.1 What is a database?","subtitle":"Informatics Grade 9 · Chapter 2 “Databases” · textbook pp. 24–25"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: ұяшық","prompt":"Электрондық кестеде баған мен жолдың қиылысы қалай аталады?","options":["Парақ","Ұяшық","Диапазон","Формула"],"answer":1,"explanation":"Баған мен жолдың қиылысы — ұяшық, мысалы C4.","points":1,"ru":{"title":"Повторение: ячейка","prompt":"Как называется пересечение столбца и строки в электронной таблице?","options":["Лист","Ячейка","Диапазон","Формула"],"explanation":"Пересечение столбца и строки — ячейка, например C4.","notes":"5 минут. Вопрос: «Как библиотекарь узнаёт, есть ли нужная книга?» Запишите ответы на доске: список, журнал, компьютер."},"en":{"title":"Review: cell","prompt":"What is the crossing of a column and a row in a spreadsheet called?","options":["Sheet","Cell","Range","Formula"],"explanation":"A column and a row cross in a cell, for example C4.","notes":"5 minutes. Ask: “How does a librarian know whether a book is in the library?” Write the answers on the board: a list, a journal, a computer."},"stage":"warmup","notes":"5 минут. Сұрақ: «Кітапханашы керек кітаптың бар-жоғын қайдан біледі?» Жауаптарды тақтаға жазыңыз: тізім, журнал, компьютер."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: SUM","prompt":"=SUM(D2:D9) формуласы не істейді?","options":["D2 мен D9 ұяшықтарын ғана қосады","Ең үлкен мәнді табады","D2-ден D9-ға дейінгі сандарды қосады","Ұяшықтар санын табады"],"answer":2,"explanation":"D2:D9 — диапазон, SUM ондағы барлық сандарды қосады.","points":1,"ru":{"title":"Повторение: SUM","prompt":"Что делает формула =SUM(D2:D9)?","options":["Складывает только D2 и D9","Находит наибольшее значение","Складывает числа от D2 до D9","Считает количество ячеек"],"explanation":"D2:D9 — диапазон, SUM складывает все числа в нём."},"en":{"title":"Review: SUM","prompt":"What does the formula =SUM(D2:D9) do?","options":["Adds only D2 and D9","Finds the largest value","Adds the numbers from D2 to D9","Counts the cells"],"explanation":"D2:D9 is a range; SUM adds every number in it."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Деректер қоры, жазба, өріс","bullets":["Деректер қоры — реттеліп сақталған деректер жиыны. Мысалы, кітапханадағы барлық кітаптың тізімі.","Деректер кестеде сақталады. Жазба (record) — бір нысан туралы мәлімет, яғни кестенің бір жолы.","Өріс (field) — бір түрдегі мәлімет сақталатын баған: атауы, авторы, жылы."],"ru":{"title":"База данных, запись, поле","bullets":["База данных — упорядоченно хранимый набор данных. Например, список всех книг библиотеки.","Данные хранятся в таблице. Запись (record) — сведения об одном объекте, то есть одна строка.","Поле (field) — столбец с данными одного вида: название, автор, год."],"notes":"8 минут (два слайда). Сравните с электронной таблицей: строка = запись, столбец = поле. Вопрос: «Что в классном журнале запись, а что поле?»"},"en":{"title":"Database, record, field","bullets":["A database is an organised collection of data. For example, the list of every book in a library.","The data live in a table. A record is the information about one item: one row.","A field is a column with one kind of information: title, author, year."],"notes":"8 minutes (two slides). Compare with a spreadsheet: a row is a record, a column is a field. Ask: “In the class register, what is a record and what is a field?”"},"stage":"together","notes":"8 минут (екі слайд). Электрондық кестемен салыстырыңыз: жол = жазба, баған = өріс. Сұрақ: «Сынып журналында жазба деген не, өріс деген не?»","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"ДҚБЖ және SQL","bullets":["ДҚБЖ (DBMS) — деректер қорын басқаратын және қорғайтын бағдарлама: Access, Oracle, PostgreSQL, MySQL, SQLite.","ДҚБЖ-да жаңа жазба қосуға, шарт бойынша іздеуге, жазбаны өшіруге болады.","SQL — деректер қорына сұраныс жазатын тіл. SELECT … FROM … — «мына өрістерді мына кестеден көрсет»."],"code":"SELECT * FROM books;\nSELECT title, author FROM books;","lang":"text","ru":{"title":"СУБД и SQL","bullets":["СУБД (DBMS) — программа, которая управляет базой данных и защищает её: Access, Oracle, PostgreSQL, MySQL, SQLite.","В СУБД можно добавлять записи, искать по условию и удалять записи.","SQL — язык запросов к базе данных. SELECT … FROM … — «покажи эти поля из этой таблицы»."]},"en":{"title":"DBMS and SQL","bullets":["A DBMS is the program that manages and protects a database: Access, Oracle, PostgreSQL, MySQL, SQLite.","With a DBMS we can add records, search by a condition and delete records.","SQL is the language of database queries. SELECT … FROM … means “show these fields from this table”."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: кітапхана кестеде","bullets":["Бұл — кітапхананың 8 кітабы. Әр жол — бір жазба (бір кітап).","Әр баған — бір өріс: атауы, жанры, жылы, саны, рейтингі.","4-жолдағы жазбаны оқы: қай кітап, қай жылы шыққан, нешеу бар?"],"demoSheet":{"rows":10,"cols":5,"cells":{"A1":"Атауы","B1":"Жанры","C1":"Жылы","D1":"Саны","E1":"Рейтингі","A2":"Абай жолы","B2":"Classical","C2":"1942","D2":"10","E2":"5","A3":"Қан мен тер","B3":"Classical","C3":"1970","D3":"4","E3":"4","A4":"Көшпенділер","B4":"History","C4":"1976","D4":"6","E4":"5","A5":"Менің атым Қожа","B5":"Adventure","C5":"1957","D5":"8","E5":"5","A6":"Шерлок Холмс","B6":"Detective","C6":"1892","D6":"5","E6":"5","A7":"Соғыс және бейбітшілік","B7":"Classical","C7":"1869","D7":"3","E7":"4","A8":"Алиса ғажайыптар елінде","B8":"Adventure","C8":"1865","D8":"7","E8":"4","A9":"Алхимик","B9":"Adventure","C9":"1988","D9":"9","E9":"3"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"C1":{"b":1,"bg":"#dbeafe"},"D1":{"b":1,"bg":"#dbeafe"},"E1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут (осы және келесі слайд). 4-жол: «Көшпенділер», History, 1976, 6 дана, рейтингі 5. Оқушылардан B бағаны қай өріс екенін сұраңыз (жанр).","ru":{"title":"Пример: библиотека в таблице","bullets":["Это 8 книг библиотеки. Каждая строка — одна запись (одна книга).","Каждый столбец — одно поле: название, жанр, год, количество, рейтинг.","Прочитай запись в строке 4: какая книга, какого года, сколько экземпляров?"],"demoSheet":{"rows":10,"cols":5,"cells":{"A1":"Название","B1":"Жанр","C1":"Год","D1":"Кол-во","E1":"Рейтинг","A2":"Абай жолы","B2":"Classical","C2":"1942","D2":"10","E2":"5","A3":"Қан мен тер","B3":"Classical","C3":"1970","D3":"4","E3":"4","A4":"Көшпенділер","B4":"History","C4":"1976","D4":"6","E4":"5","A5":"Менің атым Қожа","B5":"Adventure","C5":"1957","D5":"8","E5":"5","A6":"Шерлок Холмс","B6":"Detective","C6":"1892","D6":"5","E6":"5","A7":"Соғыс және бейбітшілік","B7":"Classical","C7":"1869","D7":"3","E7":"4","A8":"Алиса ғажайыптар елінде","B8":"Adventure","C8":"1865","D8":"7","E8":"4","A9":"Алхимик","B9":"Adventure","C9":"1988","D9":"9","E9":"3"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"C1":{"b":1,"bg":"#dbeafe"},"D1":{"b":1,"bg":"#dbeafe"},"E1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут (этот и следующий слайд). Строка 4: «Көшпенділер», History, 1976, 6 экземпляров, рейтинг 5. Спросите, какое поле в столбце B (жанр)."},"en":{"title":"Example: the library in a sheet","bullets":["These are the 8 books of the library. Every row is one record (one book).","Every column is one field: title, genre, year, quantity, rating.","Read the record in row 4: which book, which year, how many copies?"],"demoSheet":{"rows":10,"cols":5,"cells":{"A1":"Title","B1":"Genre","C1":"Year","D1":"Qty","E1":"Rating","A2":"Абай жолы","B2":"Classical","C2":"1942","D2":"10","E2":"5","A3":"Қан мен тер","B3":"Classical","C3":"1970","D3":"4","E3":"4","A4":"Көшпенділер","B4":"History","C4":"1976","D4":"6","E4":"5","A5":"Менің атым Қожа","B5":"Adventure","C5":"1957","D5":"8","E5":"5","A6":"Шерлок Холмс","B6":"Detective","C6":"1892","D6":"5","E6":"5","A7":"Соғыс және бейбітшілік","B7":"Classical","C7":"1869","D7":"3","E7":"4","A8":"Алиса ғажайыптар елінде","B8":"Adventure","C8":"1865","D8":"7","E8":"4","A9":"Алхимик","B9":"Adventure","C9":"1988","D9":"9","E9":"3"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"C1":{"b":1,"bg":"#dbeafe"},"D1":{"b":1,"bg":"#dbeafe"},"E1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 minutes (this and the next slide). Row 4: “Көшпенділер”, History, 1976, 6 copies, rating 5. Ask which field column B is (genre)."},"stage":"example"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: сол кесте SQL-де","bullets":["«Орындау» бас: SELECT * барлық өрісті көрсетеді. Жұлдызша (*) — «барлық өрістер».","Енді * орнына title, author деп жаз да, қайта орында: тек екі өріс шығады.","Өріс аттары ағылшынша және үтірмен бөлінеді. Сұраныс нүктелі үтірмен (;) аяқталады."],"code":"SELECT * FROM books;","lang":"sql","sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"SELECT * FROM books;"},"notes":"Кестедегі мен SQL-дегі деректер бірдей — бір кітапхана. Жиі қате: өріс атын қате жазу (autor) — редактор «no such column» деп қате береді. Қатені оқуды үйретіңіз.","ru":{"title":"Пример: та же таблица в SQL","bullets":["Нажми «Выполнить»: SELECT * показывает все поля. Звёздочка (*) — «все поля».","Теперь вместо * напиши title, author и выполни снова: выйдут только два поля.","Имена полей пишут по-английски через запятую. Запрос заканчивается точкой с запятой (;)."],"notes":"Данные в таблице и в SQL одинаковые — одна библиотека. Частая ошибка: опечатка в имени поля (autor) — редактор пишет «no such column». Учите читать ошибку."},"en":{"title":"Example: the same table in SQL","bullets":["Press “Run”: SELECT * shows every field. The star (*) means “all fields”.","Now type title, author instead of * and run again: only two fields appear.","Field names are in English and separated by commas. A query ends with a semicolon (;)."],"notes":"The sheet and SQL hold the same data: one library. Common slip: a misspelt field name (autor): the editor says “no such column”. Teach students to read the error."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["80467f2f"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","rows":8},"title":"Практика 1: атауы мен жылы","prompt":"books кестесінен барлық кітаптың атауы (title) мен жылын (year) көрсет. Өрістер осы ретпен тұрсын.","notes":"15 минут (үш тапсырма). Оқушы сұранысты қалағанынша орындап көре алады, бірақ жауапты бір-ақ рет жібереді. Дұрыс сұраныс: SELECT title, year FROM books;","ru":{"title":"Практика 1: название и год","prompt":"Покажи из таблицы books название (title) и год (year) всех книг. Поля — в этом порядке.","notes":"15 минут (три задания). Ученик может выполнять запрос сколько угодно раз, но ответ отправляет один раз. Верный запрос: SELECT title, year FROM books;"},"en":{"title":"Practice 1: title and year","prompt":"From the table books show the title and the year of every book. Keep the fields in this order.","notes":"15 minutes (three tasks). A student may run the query any number of times but sends the answer once. Correct query: SELECT title, year FROM books;"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 2: жазбалар саны","prompt":"books кестесінде неше жазба (record) бар? Санын жаз.","accept":["8"],"points":1,"notes":"8 жол — 8 жазба. Өрістер саны — 7 (id, title, author, genre, year, qty, rating).","ru":{"title":"Практика 2: число записей","prompt":"Сколько записей (record) в таблице books? Запиши число.","notes":"8 строк — 8 записей. Полей — 7 (id, title, author, genre, year, qty, rating)."},"en":{"title":"Practice 2: number of records","prompt":"How many records does the table books have? Type the number.","notes":"8 rows make 8 records. There are 7 fields (id, title, author, genre, year, qty, rating)."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":3,"accept":["faf73637"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","rows":4},"title":"★ Күрделі: жанрлар тізімі","prompt":"Кітапханада қандай жанрлар бар? Әр жанр бір-ақ рет шықсын. Көмек: SELECT DISTINCT genre …","notes":"Жылдам оқушыларға. DISTINCT қайталанатын мәндерді бір рет қалдырады: 8 жазбадан 4 жанр шығады.","ru":{"title":"★ Сложнее: список жанров","prompt":"Какие жанры есть в библиотеке? Каждый жанр должен выйти один раз. Подсказка: SELECT DISTINCT genre …","notes":"Для быстрых учеников. DISTINCT оставляет повторяющиеся значения по одному разу: из 8 записей получается 4 жанра."},"en":{"title":"★ Harder: the list of genres","prompt":"Which genres does the library have? Each genre must appear once. Hint: SELECT DISTINCT genre …","notes":"For fast students. DISTINCT keeps repeated values once: 8 records give 4 genres."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Жазба","prompt":"Кестедегі жазба (record) деген не?","options":["Бір нысан туралы мәлімет — бір жол","Бір түрдегі мәлімет — бір баған","Кестенің атауы","Бүкіл деректер қоры"],"answer":0,"explanation":"Жазба — жол, өріс — баған.","points":1,"ru":{"title":"Запись","prompt":"Что такое запись (record) в таблице?","options":["Сведения об одном объекте — одна строка","Данные одного вида — один столбец","Название таблицы","Вся база данных"],"explanation":"Запись — строка, поле — столбец.","notes":"7 минут: два вопроса и итог."},"en":{"title":"Record","prompt":"What is a record in a table?","options":["The information about one item: one row","One kind of information: one column","The name of the table","The whole database"],"explanation":"A record is a row, a field is a column.","notes":"7 minutes: two questions and the wrap-up."},"stage":"check","notes":"7 минут: екі сұрақ және қорытынды."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"SELECT","prompt":"SELECT title FROM books; сұранысы нені көрсетеді?","options":["Барлық өрісті","Бірінші кітапты ғана","Кестенің атауын","Барлық кітаптың атауын ғана"],"answer":3,"explanation":"SELECT-тен кейін жазылған өрістер ғана шығады: мұнда тек title, бірақ барлық 8 жазба үшін.","points":1,"ru":{"title":"SELECT","prompt":"Что покажет запрос SELECT title FROM books;?","options":["Все поля","Только первую книгу","Название таблицы","Только названия всех книг"],"explanation":"Выводятся только поля, перечисленные после SELECT: здесь только title, но для всех 8 записей."},"en":{"title":"SELECT","prompt":"What does the query SELECT title FROM books; show?","options":["Every field","Only the first book","The name of the table","Only the titles of all books"],"explanation":"Only the fields listed after SELECT are shown: here only title, but for all 8 records."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s9$::jsonb),
    ($s9$2.2 Деректер қорын жобалау$s9$, $s9$Информатика$s9$, 1, $s9${"summary":"Кестені жобалау: нені сақтаймыз, қандай өрістер, қандай деректер түрі. Кестедегі түрлер және SQL түрлері: TEXT, INTEGER, REAL, DATE. CREATE TABLE.","objectives":["Кестені жобалаудың үш сұрағына жауап беру: нысан, өрістер, түрлер","Деректер түрлерін ажырату: мәтін, сан, күн, ақша","CREATE TABLE командасымен кесте жасау"],"grade":9,"duration":"45 минут","prior":"Жазба мен өрісті ажыратады, SELECT сұранысын жаза алады (2.1 сабақ).","env":"ClassFlow кестесі және ClassFlow SQL редакторы (браузерде, орнату керек емес). Әр оқушыға бір құрылғы және интернет қажет. Google аккаунты керек емес.","source":"Информатика, 9-сынып оқулығы, 2-тарау, 26–27 беттер. Сабақ оқулықтан әдейі ауытқиды: Google Forms орнына әр тақырып кестеде және SQL-де қатар орындалады. Барлық сұраныстар мен жауаптар орындалып тексерілген, деректер оқу үшін құрастырылған.","stages":[{"k":"warmup","min":5,"do":"Өріс және ДҚБЖ туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Жобалаудың үш сұрағын және деректер түрлерін үйренеді"},{"k":"example","min":10,"do":"«Оқырмандар» кестесін кестеде жобалап, SQL-де мұғаліммен бірге жасайды"},{"k":"practice","min":15,"do":"Өзі кесте жасайды, екі қысқа сұраққа жауап береді; үлгерген оқушы ★ кестені жасайды"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Проектирование таблицы: что храним, какие поля, какие типы данных. Типы в таблице и в SQL: TEXT, INTEGER, REAL, DATE. CREATE TABLE.","objectives":["Отвечать на три вопроса проектирования: объект, поля, типы","Различать типы данных: текст, число, дата, деньги","Создавать таблицу командой CREATE TABLE"],"prior":"Различают запись и поле, умеют писать запрос SELECT (урок 2.1).","env":"Таблица ClassFlow и SQL-редактор ClassFlow (в браузере, устанавливать ничего не нужно). Каждому ученику нужны устройство и интернет. Аккаунт Google не нужен.","source":"Информатика, учебник 9 класса, глава 2, с. 26–27. Урок намеренно отходит от учебника: вместо Google Forms каждая тема выполняется параллельно в таблице и в SQL. Все запросы и ответы проверены выполнением, данные учебные.","stages":["Отвечает на два вопроса о поле и СУБД","Изучает три вопроса проектирования и типы данных","Проектирует таблицу «Читатели» и создаёт её в SQL вместе с учителем","Сам создаёт таблицу и отвечает на два коротких вопроса; кто успел — таблицу ★","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"Designing a table: what we store, which fields, which data types. Types in a sheet and in SQL: TEXT, INTEGER, REAL, DATE. CREATE TABLE.","objectives":["Answer the three design questions: item, fields, types","Tell data types apart: text, number, date, money","Create a table with CREATE TABLE"],"prior":"Tell a record from a field and can write a SELECT query (lesson 2.1).","env":"The ClassFlow sheet and the ClassFlow SQL editor (in the browser, nothing to install). One device per student and the internet. No Google account is needed.","source":"Informatics, Grade 9 textbook, chapter 2, pp. 26–27. The lesson leaves the textbook on purpose: instead of Google Forms every topic is done side by side in a sheet and in SQL. Every query and answer was run; the data are made for the classroom.","stages":["Answers two questions about fields and DBMS","Learns the three design questions and the data types","Designs the “Readers” table in a sheet and creates it in SQL with the teacher","Creates a table alone and answers two short questions; fast students build the ★ table","Takes a short test and says what was learned"]}}$s9$::jsonb, $s9$[{"term":"data type","definition":"Деректер түрі — өрісте қандай мән сақталатыны: мәтін, сан, күн · Тип данных — какое значение хранится в поле: текст, число, дата · Data type — what kind of value a field stores: text, number, date"},{"term":"TEXT","definition":"TEXT — мәтін: аты, тегі, мекенжайы · TEXT — текст: имя, фамилия, адрес · TEXT — text: a name, a surname, an address"},{"term":"INTEGER","definition":"INTEGER — бүтін сан: жасы, саны · INTEGER — целое число: возраст, количество · INTEGER — a whole number: age, quantity"},{"term":"REAL","definition":"REAL — бөлшек сан: бағасы, салмағы · REAL — дробное число: цена, вес · REAL — a number with a fraction: price, weight"},{"term":"CREATE TABLE","definition":"CREATE TABLE — жаңа кесте жасайтын команда · CREATE TABLE — команда, создающая новую таблицу · CREATE TABLE — the command that makes a new table"}]$s9$::jsonb, $s9$[{"type":"title","pageType":"slide","templateId":"title","title":"2.2 Деректер қорын жобалау","subtitle":"Информатика 9-сынып · 2-тарау «Деректер қоры» · оқулық 26–27-б.","ru":{"title":"2.2 Проектирование базы данных","subtitle":"Информатика 9 класс · глава 2 «Базы данных» · учебник, с. 26–27"},"en":{"title":"2.2 Designing a database","subtitle":"Informatics Grade 9 · Chapter 2 “Databases” · textbook pp. 26–27"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: өріс","prompt":"Кестедегі өріс (field) деген не?","options":["Кестенің бір жолы","Сұраныстың нәтижесі","Бір түрдегі мәлімет сақталатын баған","Кестенің атауы"],"answer":2,"explanation":"Өріс — баған: онда бір түрдегі мәлімет сақталады.","points":1,"ru":{"title":"Повторение: поле","prompt":"Что такое поле (field) в таблице?","options":["Одна строка таблицы","Результат запроса","Столбец с данными одного вида","Название таблицы"],"explanation":"Поле — столбец: в нём хранятся данные одного вида.","notes":"5 минут. Вопрос: «Как лучше всего хранить сведения о книгах библиотеки?»"},"en":{"title":"Review: field","prompt":"What is a field in a table?","options":["One row of a table","The result of a query","A column with one kind of information","The name of the table"],"explanation":"A field is a column: it stores one kind of information.","notes":"5 minutes. Ask: “What is the best way to keep information about the books of a library?”"},"stage":"warmup","notes":"5 минут. Сұрақ: «Кітапханадағы кітаптар туралы мәліметті сақтаудың ең жақсы жолы қандай?»"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: ДҚБЖ","prompt":"Төмендегілердің қайсысы ДҚБЖ?","options":["MySQL","Paint","Google Chrome","Блокнот"],"answer":0,"explanation":"MySQL, PostgreSQL, Oracle, Access, SQLite — деректер қорын басқару жүйелері.","points":1,"ru":{"title":"Повторение: СУБД","prompt":"Что из перечисленного — СУБД?","options":["MySQL","Paint","Google Chrome","Блокнот"],"explanation":"MySQL, PostgreSQL, Oracle, Access, SQLite — системы управления базами данных."},"en":{"title":"Review: DBMS","prompt":"Which of these is a DBMS?","options":["MySQL","Paint","Google Chrome","Notepad"],"explanation":"MySQL, PostgreSQL, Oracle, Access and SQLite are database management systems."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Кестені жобалау: үш сұрақ","bullets":["Не туралы мәлімет сақтаймыз? Жауабы кестенің атауын береді: кітаптар — books.","Қандай өрістер керек? Жауабы өріс аттарын береді: атауы, авторы, жылы, саны.","Әр өрісте қандай түрдегі дерек болады? Жауабы өрістің түрін береді."],"ru":{"title":"Проектирование таблицы: три вопроса","bullets":["О чём храним сведения? Ответ даёт имя таблицы: книги — books.","Какие поля нужны? Ответ даёт имена полей: название, автор, год, количество.","Данные какого типа будут в каждом поле? Ответ даёт тип поля."],"notes":"8 минут (два слайда). Оставьте три вопроса на доске. Для примера спроектируйте вместе таблицу «Ученики»."},"en":{"title":"Designing a table: three questions","bullets":["What do we keep information about? The answer names the table: books.","Which fields do we need? The answer gives the field names: title, author, year, quantity.","What type of data goes in each field? The answer gives the field type."],"notes":"8 minutes (two slides). Keep the three questions on the board. Design a “Students” table together as an example."},"stage":"together","notes":"8 минут (екі слайд). Үш сұрақты тақтада қалдырыңыз. Мысал ретінде «Оқушылар» кестесін бірге жобалаңыз.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Деректер түрлері: кестеде және SQL-де","bullets":["Мәтін (Text) — аты, тегі, мекенжайы. SQL-де: TEXT.","Сан (Number) — жасы, саны, салмағы. SQL-де: бүтін сан INTEGER, бөлшек сан REAL.","Күн (Date) — туған күні, шыққан күні. SQL-де: DATE. Ақша (Currency) — бағасы; SQL-де оны REAL түрімен сақтаймыз."],"code":"title   TEXT\nqty     INTEGER\nprice   REAL\nbirth   DATE","lang":"text","ru":{"title":"Типы данных: в таблице и в SQL","bullets":["Текст (Text) — имя, фамилия, адрес. В SQL: TEXT.","Число (Number) — возраст, количество, вес. В SQL: целое INTEGER, дробное REAL.","Дата (Date) — день рождения, дата выпуска. В SQL: DATE. Деньги (Currency) — цена; в SQL храним её как REAL."]},"en":{"title":"Data types: in a sheet and in SQL","bullets":["Text: names, surnames, addresses. In SQL: TEXT.","Number: age, amount, weight. In SQL: INTEGER for whole numbers, REAL for fractions.","Date: a birthday, a production date. In SQL: DATE. Currency: a price; in SQL we store it as REAL."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: «Оқырмандар» кестесінің жобасы","bullets":["1-жолда өріс аттары тұр: id, name, class, birth.","2-жолға әр өрістің түрін жаз: INTEGER, TEXT, TEXT, DATE.","3-жолға бір мысал жазба қос. Әр мән өз түріне сай ма?"],"demoSheet":{"rows":6,"cols":4,"cells":{"A1":"id","B1":"name","C1":"class","D1":"birth","A3":"1","B3":"Айым Серік","C3":"9A","D3":"2011-05-14"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"C1":{"b":1,"bg":"#dbeafe"},"D1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут (осы және келесі слайд). 2-жолды оқушылармен бірге толтырыңыз. Сұрақ: «Сынып (9A) неге сан емес?» — онда әріп бар және онымен есептемейміз.","ru":{"title":"Пример: проект таблицы «Читатели»","bullets":["В строке 1 — имена полей: id, name, class, birth.","В строку 2 запиши тип каждого поля: INTEGER, TEXT, TEXT, DATE.","В строку 3 добавь одну запись-пример. Соответствует ли каждое значение своему типу?"],"demoSheet":{"rows":6,"cols":4,"cells":{"A1":"id","B1":"name","C1":"class","D1":"birth","A3":"1","B3":"Айым Серик","C3":"9A","D3":"2011-05-14"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"C1":{"b":1,"bg":"#dbeafe"},"D1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут (этот и следующий слайд). Строку 2 заполните вместе с классом. Вопрос: «Почему класс (9A) не число?» — в нём есть буква, и с ним не считают."},"en":{"title":"Example: the design of the “Readers” table","bullets":["Row 1 holds the field names: id, name, class, birth.","In row 2 type the type of each field: INTEGER, TEXT, TEXT, DATE.","Add one sample record to row 3. Does each value fit its type?"],"demoSheet":{"rows":6,"cols":4,"cells":{"A1":"id","B1":"name","C1":"class","D1":"birth","A3":"1","B3":"Aiym Serik","C3":"9A","D3":"2011-05-14"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"C1":{"b":1,"bg":"#dbeafe"},"D1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 minutes (this and the next slide). Fill row 2 with the class. Ask: “Why is the class (9A) not a number?” It has a letter and we do not calculate with it."},"stage":"example"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: кестені SQL-де жасау","bullets":["CREATE TABLE кестенің атын, жақша ішінде өрістерін және әр өрістің түрін жазады.","«Орындау» бас. Кесте жасалды, бірақ бос: екінші команда бір жазба қосады.","Соңғы команда SELECT кестені көрсетеді. Әр команда нүктелі үтірмен аяқталады."],"code":"CREATE TABLE readers (id INTEGER, name TEXT, class TEXT, birth DATE);\nINSERT INTO readers VALUES (1, 'Айым Серік', '9A', '2011-05-14');\nSELECT * FROM readers;","lang":"sql","sql":{"setup":"","start":"CREATE TABLE readers (id INTEGER, name TEXT, class TEXT, birth DATE);\nINSERT INTO readers VALUES (1, 'Айым Серік', '9A', '2011-05-14');\nSELECT * FROM readers;"},"notes":"Жоба кестеде, орындалуы SQL-де — бірдей өрістер. Жиі қате: өрістер арасындағы үтірді немесе жабатын жақшаны ұмыту («syntax error»).","ru":{"title":"Пример: создание таблицы в SQL","bullets":["CREATE TABLE задаёт имя таблицы, а в скобках — поля и тип каждого поля.","Нажми «Выполнить». Таблица создана, но пуста: вторая команда добавляет одну запись.","Последняя команда SELECT показывает таблицу. Каждая команда заканчивается точкой с запятой."],"notes":"Проект — в таблице, выполнение — в SQL: поля одинаковые. Частая ошибка: забыть запятую между полями или закрывающую скобку («syntax error»)."},"en":{"title":"Example: creating the table in SQL","bullets":["CREATE TABLE gives the table name and, in brackets, the fields with the type of each.","Press “Run”. The table is made but empty: the second command adds one record.","The last command, SELECT, shows the table. Every command ends with a semicolon."],"notes":"The design is in the sheet, the build in SQL: the same fields. Common slip: a missing comma between fields or a missing closing bracket (“syntax error”)."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["c994cd2f"],"sql":{"setup":"","start":"","probe":"SELECT name FROM pragma_table_info('members');","ordered":true,"rows":3},"title":"Практика 1: members кестесі","prompt":"Кітапхана мүшелері үшін members кестесін жаса. Өрістері осы ретпен: id (INTEGER), name (TEXT), class (TEXT).","notes":"15 минут (төрт тапсырма). Тексеру кестенің өріс аттары мен ретін салыстырады. Дұрыс команда: CREATE TABLE members (id INTEGER, name TEXT, class TEXT);","ru":{"title":"Практика 1: таблица members","prompt":"Создай таблицу members для читателей библиотеки. Поля в таком порядке: id (INTEGER), name (TEXT), class (TEXT).","notes":"15 минут (четыре задания). Проверка сравнивает имена и порядок полей таблицы. Верная команда: CREATE TABLE members (id INTEGER, name TEXT, class TEXT);"},"en":{"title":"Practice 1: the table members","prompt":"Create the table members for the library members. Fields in this order: id (INTEGER), name (TEXT), class (TEXT).","notes":"15 minutes (four tasks). The check compares the names and the order of the fields. Correct command: CREATE TABLE members (id INTEGER, name TEXT, class TEXT);"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 2: түрді таңда","prompt":"Кітаптың шыққан жылын (мысалы, 1976) сақтайтын өріске қандай SQL түрі сәйкес келеді? Бір сөзбен жаз.","accept":["integer","int"],"points":1,"notes":"Жыл — бүтін сан: INTEGER.","ru":{"title":"Практика 2: выбери тип","prompt":"Какой тип SQL подходит полю, где хранится год издания книги (например, 1976)? Напиши одним словом.","notes":"Год — целое число: INTEGER."},"en":{"title":"Practice 2: pick the type","prompt":"Which SQL type fits a field that stores the year of a book (for example 1976)? One word.","notes":"A year is a whole number: INTEGER."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 3: баға","prompt":"Бағасы 1250.50 сияқты бөлшек сан сақталатын өріске қандай SQL түрі керек? Бір сөзбен жаз.","accept":["real"],"points":1,"notes":"Бөлшек сан — REAL.","ru":{"title":"Практика 3: цена","prompt":"Какой тип SQL нужен полю с дробным числом вроде цены 1250.50? Напиши одним словом.","notes":"Дробное число — REAL."},"en":{"title":"Practice 3: price","prompt":"Which SQL type does a field with a fractional number such as the price 1250.50 need? One word.","notes":"A number with a fraction is REAL."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":3,"accept":["8a7693d3"],"sql":{"setup":"","start":"","probe":"SELECT name, type FROM pragma_table_info('movies');","ordered":true,"rows":4},"title":"★ Күрделі: movies кестесі","prompt":"Фильмдер қорын жобала: movies кестесі, өрістері осы ретпен және осы түрлермен: id INTEGER, title TEXT, year INTEGER, price REAL.","notes":"Жылдам оқушыларға. Мұнда өріс аттарымен бірге түрлері де тексеріледі: түр дәл тапсырмадағыдай жазылуы керек (INT емес, INTEGER).","ru":{"title":"★ Сложнее: таблица movies","prompt":"Спроектируй базу фильмов: таблица movies, поля в таком порядке и с такими типами: id INTEGER, title TEXT, year INTEGER, price REAL.","notes":"Для быстрых учеников. Здесь проверяются и имена полей, и типы: тип нужно написать точно как в задании (INTEGER, а не INT)."},"en":{"title":"★ Harder: the table movies","prompt":"Design a film database: the table movies with these fields and types in this order: id INTEGER, title TEXT, year INTEGER, price REAL.","notes":"For fast students. Both the field names and the types are checked: write the type exactly as in the task (INTEGER, not INT)."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Күн түрі","prompt":"Оқушының туған күнін сақтайтын өріске қай түр сәйкес келеді?","options":["TEXT","DATE","INTEGER","REAL"],"answer":1,"explanation":"Туған күн — күн: DATE.","points":1,"ru":{"title":"Тип даты","prompt":"Какой тип подходит полю с датой рождения ученика?","options":["TEXT","DATE","INTEGER","REAL"],"explanation":"День рождения — дата: DATE.","notes":"7 минут: два вопроса и итог."},"en":{"title":"Date type","prompt":"Which type fits a field with a student’s birthday?","options":["TEXT","DATE","INTEGER","REAL"],"explanation":"A birthday is a date: DATE.","notes":"7 minutes: two questions and the wrap-up."},"stage":"check","notes":"7 минут: екі сұрақ және қорытынды."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"CREATE TABLE","prompt":"CREATE TABLE командасы не істейді?","options":["Кестедегі жазбаларды көрсетеді","Кестеге жазба қосады","Кестені өшіреді","Өрістері мен түрлері бар жаңа бос кесте жасайды"],"answer":3,"explanation":"CREATE TABLE — жаңа кесте; SELECT — көрсету; INSERT — жазба қосу.","points":1,"ru":{"title":"CREATE TABLE","prompt":"Что делает команда CREATE TABLE?","options":["Показывает записи таблицы","Добавляет запись в таблицу","Удаляет таблицу","Создаёт новую пустую таблицу с полями и типами"],"explanation":"CREATE TABLE — новая таблица; SELECT — показать; INSERT — добавить запись."},"en":{"title":"CREATE TABLE","prompt":"What does CREATE TABLE do?","options":["Shows the records of a table","Adds a record to a table","Deletes a table","Makes a new empty table with fields and types"],"explanation":"CREATE TABLE makes a table; SELECT shows; INSERT adds a record."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s9$::jsonb),
    ($s9$2.3 Деректер қорын құру$s9$, $s9$Информатика$s9$, 2, $s9${"summary":"Кестеге жазба қосу: кестеде жол толтыру, SQL-де INSERT INTO. Мәтін тырнақшада, сан тырнақшасыз. Бос мән — NULL.","objectives":["Кестеге жазбаларды қатесіз енгізу","INSERT INTO командасымен жазба қосу","Мәтін мен санның жазылу айырмасын түсіну"],"grade":9,"duration":"45 минут","prior":"CREATE TABLE командасымен кесте жасай алады, деректер түрлерін біледі (2.2 сабақ).","env":"ClassFlow кестесі және ClassFlow SQL редакторы (браузерде, орнату керек емес). Әр оқушыға бір құрылғы және интернет қажет. Google аккаунты керек емес.","source":"Информатика, 9-сынып оқулығы, 2-тарау, 28–29 беттер. Сабақ оқулықтан әдейі ауытқиды: Google Forms орнына әр тақырып кестеде және SQL-де қатар орындалады. Барлық сұраныстар мен жауаптар орындалып тексерілген, деректер оқу үшін құрастырылған.","stages":[{"k":"warmup","min":5,"do":"CREATE TABLE және түрлер туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"INSERT INTO командасының жазылуын үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге кітапханаға бір кітап қосады"},{"k":"practice","min":15,"do":"Кестеге төрт кітап енгізеді, SQL-де екі кітап қосады; үлгерген оқушы ★ тапсырманы орындайды"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Добавление записей: в таблице — заполнение строки, в SQL — INSERT INTO. Текст в кавычках, число без кавычек. Пустое значение — NULL.","objectives":["Вводить записи в таблицу без ошибок","Добавлять запись командой INSERT INTO","Понимать разницу в записи текста и числа"],"prior":"Умеют создавать таблицу командой CREATE TABLE и знают типы данных (урок 2.2).","env":"Таблица ClassFlow и SQL-редактор ClassFlow (в браузере, устанавливать ничего не нужно). Каждому ученику нужны устройство и интернет. Аккаунт Google не нужен.","source":"Информатика, учебник 9 класса, глава 2, с. 28–29. Урок намеренно отходит от учебника: вместо Google Forms каждая тема выполняется параллельно в таблице и в SQL. Все запросы и ответы проверены выполнением, данные учебные.","stages":["Отвечает на два вопроса о CREATE TABLE и типах","Изучает запись команды INSERT INTO","Вместе с учителем добавляет в библиотеку одну книгу","Вводит в таблицу четыре книги, в SQL добавляет две; кто успел — задание ★","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"Adding records: filling a row in a sheet, INSERT INTO in SQL. Text in quotes, numbers without. An empty value is NULL.","objectives":["Enter records into a table without mistakes","Add a record with INSERT INTO","Understand how text and numbers are written differently"],"prior":"Can create a table with CREATE TABLE and know the data types (lesson 2.2).","env":"The ClassFlow sheet and the ClassFlow SQL editor (in the browser, nothing to install). One device per student and the internet. No Google account is needed.","source":"Informatics, Grade 9 textbook, chapter 2, pp. 28–29. The lesson leaves the textbook on purpose: instead of Google Forms every topic is done side by side in a sheet and in SQL. Every query and answer was run; the data are made for the classroom.","stages":["Answers two questions about CREATE TABLE and types","Learns how INSERT INTO is written","Adds one book to the library with the teacher","Types four books into a sheet and adds two in SQL; fast students take the ★ task","Takes a short test and says what was learned"]}}$s9$::jsonb, $s9$[{"term":"INSERT INTO","definition":"INSERT INTO — кестеге жаңа жазба қосатын команда · INSERT INTO — команда, добавляющая новую запись · INSERT INTO — the command that adds a new record"},{"term":"VALUES","definition":"VALUES — жаңа жазбаның мәндері, өрістер ретімен · VALUES — значения новой записи в порядке полей · VALUES — the values of the new record, in field order"},{"term":"NULL","definition":"NULL — мәні жоқ бос өріс · NULL — пустое поле без значения · NULL — an empty field with no value"}]$s9$::jsonb, $s9$[{"type":"title","pageType":"slide","templateId":"title","title":"2.3 Деректер қорын құру","subtitle":"Информатика 9-сынып · 2-тарау «Деректер қоры» · оқулық 28–29-б.","ru":{"title":"2.3 Создание базы данных","subtitle":"Информатика 9 класс · глава 2 «Базы данных» · учебник, с. 28–29"},"en":{"title":"2.3 Building a database","subtitle":"Informatics Grade 9 · Chapter 2 “Databases” · textbook pp. 28–29"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: CREATE TABLE","prompt":"CREATE TABLE books (…); орындалғаннан кейін books кестесінде неше жазба болады?","options":["8","1","Өрістер саны қанша болса, сонша","0 — кесте бос"],"answer":3,"explanation":"CREATE TABLE тек кестенің құрылымын жасайды, жазбалар кейін қосылады.","points":1,"ru":{"title":"Повторение: CREATE TABLE","prompt":"Сколько записей будет в таблице books сразу после CREATE TABLE books (…);?","options":["8","1","Столько же, сколько полей","0 — таблица пуста"],"explanation":"CREATE TABLE создаёт только структуру таблицы, записи добавляют потом.","notes":"5 минут. Вопрос: «Как добавить в базу новую книгу, которая пришла в библиотеку?»"},"en":{"title":"Review: CREATE TABLE","prompt":"How many records does books have right after CREATE TABLE books (…);?","options":["8","1","As many as there are fields","0: the table is empty"],"explanation":"CREATE TABLE only makes the structure; records are added later.","notes":"5 minutes. Ask: “When a new book arrives, how do we add it to the database?”"},"stage":"warmup","notes":"5 минут. Сұрақ: «Кітапханаға жаңа кітап келгенде оны қорға қалай қосамыз?»"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: түр","prompt":"Кітаптың авторы сақталатын өрістің түрі қандай?","options":["INTEGER","TEXT","REAL","DATE"],"answer":1,"explanation":"Автордың аты — мәтін: TEXT.","points":1,"ru":{"title":"Повторение: тип","prompt":"Какой тип у поля, где хранится автор книги?","options":["INTEGER","TEXT","REAL","DATE"],"explanation":"Имя автора — текст: TEXT."},"en":{"title":"Review: type","prompt":"Which type does the field with the author of a book have?","options":["INTEGER","TEXT","REAL","DATE"],"explanation":"An author’s name is text: TEXT."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Жазба қосу: кестеде және SQL-де","bullets":["Оқулықта жазба Google Forms арқылы қосылады: форма толтырылады да, кестеге жаңа жол түседі.","Кестеде жаңа жазба — жаңа жол: әр ұяшыққа өз өрісінің мәнін жазамыз.","SQL-де: INSERT INTO кесте VALUES (мәндер). Мәндер өрістердің ретімен, үтірмен бөлініп жазылады."],"code":"INSERT INTO books VALUES\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5);","lang":"text","ru":{"title":"Добавление записи: в таблице и в SQL","bullets":["В учебнике записи добавляют через Google Forms: форму заполняют, и в таблице появляется новая строка.","В таблице новая запись — новая строка: в каждую ячейку пишем значение своего поля.","В SQL: INSERT INTO таблица VALUES (значения). Значения идут в порядке полей через запятую."],"notes":"8 минут (два слайда). Подчеркните: форма, строка таблицы и INSERT — три вида одного действия."},"en":{"title":"Adding a record: in a sheet and in SQL","bullets":["In the textbook records are added with Google Forms: a filled form becomes a new row of the table.","In a sheet a new record is a new row: each cell gets the value of its field.","In SQL: INSERT INTO table VALUES (values). The values follow the field order, separated by commas."],"notes":"8 minutes (two slides). Stress that a form, a sheet row and INSERT are three forms of the same action."},"stage":"together","notes":"8 минут (екі слайд). Форма, кесте жолы және INSERT — бір әрекеттің үш түрі екенін айтыңыз.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Мәтін, сан және бос мән","bullets":["Мәтін бір тырнақшаға алынады: 'Абай жолы'. Сан тырнақшасыз жазылады: 1942.","Тек кейбір өрістерді толтыруға болады: INSERT INTO books (id, title) VALUES (9, 'Жаңа кітап').","Толтырылмаған өрісте NULL тұрады — «мәні жоқ». NULL нөл де, бос мәтін де емес."],"ru":{"title":"Текст, число и пустое значение","bullets":["Текст берут в одинарные кавычки: 'Абай жолы'. Число пишут без кавычек: 1942.","Можно заполнить только часть полей: INSERT INTO books (id, title) VALUES (9, 'Новая книга').","В незаполненном поле стоит NULL — «нет значения». NULL — это не ноль и не пустой текст."]},"en":{"title":"Text, numbers and empty values","bullets":["Text goes in single quotes: 'Абай жолы'. A number is written without quotes: 1942.","You may fill only some fields: INSERT INTO books (id, title) VALUES (9, 'New book').","An unfilled field holds NULL: “no value”. NULL is neither zero nor an empty text."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: кітапханаға кітап қосу","bullets":["Кестеде екі кітап бар. «Орындау» бас: INSERT үшінші кітапты қосады, SELECT кестені көрсетеді.","Мәндерді өрістермен салыстыр: id, title, author, genre, year, qty, rating — жеті өріс, жеті мән.","Бір тырнақшаны өшіріп, қайта орында: редактор қатені көрсетеді. Тырнақшаны қайтар."],"code":"INSERT INTO books VALUES (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5);\nSELECT * FROM books;","lang":"sql","sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4);","start":"INSERT INTO books VALUES (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5);\nSELECT * FROM books;"},"notes":"10 минут. Редактор әр орындауда кестені бастапқы күйден (екі кітап) бастайды, сондықтан INSERT-ті қайта орындағанда жазба қайталанбайды. Мұны оқушыларға айтыңыз.","ru":{"title":"Пример: добавляем книгу в библиотеку","bullets":["В таблице две книги. Нажми «Выполнить»: INSERT добавит третью, SELECT покажет таблицу.","Сопоставь значения с полями: id, title, author, genre, year, qty, rating — семь полей, семь значений.","Удали одну кавычку и выполни снова: редактор покажет ошибку. Верни кавычку."],"notes":"10 минут. При каждом запуске редактор начинает с исходной таблицы (две книги), поэтому повторный INSERT не дублирует запись. Скажите об этом ученикам."},"en":{"title":"Example: adding a book to the library","bullets":["The table has two books. Press “Run”: INSERT adds a third one and SELECT shows the table.","Match the values to the fields: id, title, author, genre, year, qty, rating: seven fields, seven values.","Delete one quote and run again: the editor shows an error. Put the quote back."],"notes":"10 minutes. Every run starts from the original table (two books), so running INSERT again does not duplicate the record. Tell the students."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 1: кестеге төрт кітап","prompt":"Суреттегі төрт жазбаны кестеге енгіз. Кітаптардың жалпы санын және ең ескі кітаптың жылын формуламен тап.","points":6,"picture":"lec/inf8-g9-build-kk.svg","pictureAlt":"Төрт кітаптың атауы, жанры, жылы, саны және рейтингі; жалпы сан мен ең ескі жыл бос","sheet":{"rows":10,"cols":6},"criteria":[{"id":"c1","text":"Жазбалар енгізілген: D5 = 5","cell":"D5","points":1,"accept":["5"]},{"id":"c2","text":"Жылдар енгізілген: C3 = 1976","cell":"C3","points":1,"accept":["1976"]},{"id":"c3","text":"D6 — кітаптардың жалпы саны (SUM)","cell":"D6","points":2,"fn":"SUM","accept":["29"]},{"id":"c4","text":"★ C7 — ең ескі кітаптың жылы (MIN)","cell":"C7","points":2,"fn":"MIN","accept":["1892"]}],"notes":"15 минут (үш тапсырма). Күтілетін нәтиже: D6 = 29, C7 = 1892. Жиі қате: жанрды әр жолда әртүрлі жазу (History, history, Тарих) — кейін сүзу мен топтауда қиындық туғызады.","ru":{"title":"Практика 1: четыре книги в таблице","prompt":"Введи в таблицу четыре записи с рисунка. Формулами найди общее количество книг и год самой старой книги.","picture":"lec/inf8-g9-build-ru.svg","pictureAlt":"Название, жанр, год, количество и рейтинг четырёх книг; общее количество и самый старый год пустые","criteria":[{"id":"c1","text":"Записи введены: D5 = 5","cell":"D5","points":1},{"id":"c2","text":"Годы введены: C3 = 1976","cell":"C3","points":1},{"id":"c3","text":"D6 — общее количество книг (SUM)","cell":"D6","points":2,"fn":"SUM"},{"id":"c4","text":"★ C7 — год самой старой книги (MIN)","cell":"C7","points":2,"fn":"MIN"}],"notes":"15 минут (три задания). Ожидаемый результат: D6 = 29, C7 = 1892. Частая ошибка: писать жанр по-разному (History, history, История) — потом это мешает фильтру и группировке."},"en":{"title":"Practice 1: four books in a sheet","prompt":"Type the four records from the picture into the sheet. With formulas find the total number of copies and the year of the oldest book.","picture":"lec/inf8-g9-build-en.svg","pictureAlt":"Title, genre, year, quantity and rating of four books; the total and the oldest year are empty","criteria":[{"id":"c1","text":"Records entered: D5 = 5","cell":"D5","points":1},{"id":"c2","text":"Years entered: C3 = 1976","cell":"C3","points":1},{"id":"c3","text":"D6 — the total number of copies (SUM)","cell":"D6","points":2,"fn":"SUM"},{"id":"c4","text":"★ C7 — the year of the oldest book (MIN)","cell":"C7","points":2,"fn":"MIN"}],"notes":"15 minutes (three tasks). Expected: D6 = 29, C7 = 1892. Common slip: spelling the genre differently in each row (History, history): it breaks filtering and grouping later."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["c02f667a"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4);","start":"INSERT INTO books VALUES (","probe":"SELECT id, title, genre, year, qty FROM books;","rows":4},"title":"Практика 2: екі кітап қос","prompt":"books кестесіне екі жазба қос: (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5) және (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5).","notes":"Тексеру кестедегі төрт жазбаның id, атауы, жанры, жылы және санын салыстырады. Мәтінді тапсырмадан көшіріп алуға болады.","ru":{"title":"Практика 2: добавь две книги","prompt":"Добавь в таблицу books две записи: (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5) и (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5).","notes":"Проверка сравнивает id, название, жанр, год и количество четырёх записей. Текст можно скопировать из задания."},"en":{"title":"Practice 2: add two books","prompt":"Add two records to books: (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5) and (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5).","notes":"The check compares id, title, genre, year and quantity of the four records. The text may be copied from the task."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":3,"accept":["22b1bba4"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4);","start":"","probe":"SELECT id, title, author, qty FROM books;","rows":3},"title":"★ Күрделі: толық емес жазба","prompt":"Жаңа кітаптың тек нөмірі, атауы және саны белгілі: 5, 'Шерлок Холмс', 5. Оны тек осы үш өрісті (id, title, qty) көрсетіп қос.","notes":"Жылдам оқушыларға. Дұрыс команда: INSERT INTO books (id, title, qty) VALUES (5, 'Шерлок Холмс', 5); Автор өрісінде NULL шығады — оқушыдан неге екенін сұраңыз.","ru":{"title":"★ Сложнее: неполная запись","prompt":"У новой книги известны только номер, название и количество: 5, 'Шерлок Холмс', 5. Добавь её, указав только эти три поля (id, title, qty).","notes":"Для быстрых учеников. Верная команда: INSERT INTO books (id, title, qty) VALUES (5, 'Шерлок Холмс', 5); В поле автора будет NULL — спросите ученика почему."},"en":{"title":"★ Harder: an incomplete record","prompt":"Only the number, the title and the quantity of a new book are known: 5, 'Шерлок Холмс', 5. Add it naming just these three fields (id, title, qty).","notes":"For fast students. Correct command: INSERT INTO books (id, title, qty) VALUES (5, 'Шерлок Холмс', 5); The author field shows NULL: ask the student why."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тырнақша","prompt":"INSERT командасында қай мән тырнақшаға алынады?","options":["Мәтін: 'Абай жолы'","Сан: 1942","Кестенің аты: books","Команданың өзі: INSERT"],"answer":0,"explanation":"Мәтін бір тырнақшаға алынады, сан мен кесте аты — жоқ.","points":1,"ru":{"title":"Кавычки","prompt":"Какое значение в команде INSERT берут в кавычки?","options":["Текст: 'Абай жолы'","Число: 1942","Имя таблицы: books","Сама команда: INSERT"],"explanation":"Текст берут в одинарные кавычки, число и имя таблицы — нет.","notes":"7 минут: два вопроса и итог."},"en":{"title":"Quotes","prompt":"Which value goes in quotes in an INSERT command?","options":["Text: 'Абай жолы'","A number: 1942","The table name: books","The command itself: INSERT"],"explanation":"Text goes in single quotes; numbers and table names do not.","notes":"7 minutes: two questions and the wrap-up."},"stage":"check","notes":"7 минут: екі сұрақ және қорытынды."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"NULL","prompt":"Жазбаны қосқанда author өрісі көрсетілмеді. Ол өрісте не тұрады?","options":["0","Алдыңғы жазбаның авторы","NULL — мәні жоқ","Қате шығады, жазба қосылмайды"],"answer":2,"explanation":"Көрсетілмеген өріс NULL болады: «мәні жоқ».","points":1,"ru":{"title":"NULL","prompt":"При добавлении записи поле author не указали. Что будет в этом поле?","options":["0","Автор предыдущей записи","NULL — нет значения","Будет ошибка, запись не добавится"],"explanation":"Неуказанное поле получает NULL: «нет значения»."},"en":{"title":"NULL","prompt":"A record was added without the author field. What does that field hold?","options":["0","The author of the previous record","NULL: no value","An error: the record is not added"],"explanation":"A field that was not named gets NULL: “no value”."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s9$::jsonb),
    ($s9$2.4 Деректерді сұрыптау және сүзу$s9$, $s9$Информатика$s9$, 3, $s9${"summary":"Көп деректен керегін табу: сүзу (шарт бойынша таңдау) және сұрыптау (ретке келтіру). Кестеде COUNTIF, SQL-де WHERE және ORDER BY.","objectives":["Сүзу мен сұрыптаудың айырмасын түсіндіру","WHERE шартымен жазбаларды таңдау","ORDER BY көмегімен нәтижені өсу немесе кему ретімен шығару"],"grade":9,"duration":"45 минут","prior":"SELECT және INSERT командаларын жаза алады; кестеде COUNT, MIN, MAX функцияларын біледі (2.3 сабақ, 8-сынып).","env":"ClassFlow кестесі және ClassFlow SQL редакторы (браузерде, орнату керек емес). Әр оқушыға бір құрылғы және интернет қажет. Google аккаунты керек емес.","source":"Информатика, 9-сынып оқулығы, 2-тарау, 30–31 беттер. Сабақ оқулықтан әдейі ауытқиды: Google Forms орнына әр тақырып кестеде және SQL-де қатар орындалады. Барлық сұраныстар мен жауаптар орындалып тексерілген, деректер оқу үшін құрастырылған.","stages":[{"k":"warmup","min":5,"do":"INSERT және SELECT туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Сүзу мен сұрыптауды, WHERE және ORDER BY жазылуын үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге саны 5-тен көп кітаптарды кему ретімен шығарады"},{"k":"practice","min":15,"do":"Кестеде шарт бойынша санайды, SQL-де екі сұраныс жазады; үлгерген оқушы ★ сұранысты орындайды"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Как найти нужное среди множества данных: фильтр (отбор по условию) и сортировка (упорядочение). В таблице — COUNTIF, в SQL — WHERE и ORDER BY.","objectives":["Объяснять разницу между фильтром и сортировкой","Отбирать записи условием WHERE","Выводить результат по возрастанию или убыванию с ORDER BY"],"prior":"Умеют писать SELECT и INSERT; знают функции COUNT, MIN, MAX в таблице (урок 2.3, 8 класс).","env":"Таблица ClassFlow и SQL-редактор ClassFlow (в браузере, устанавливать ничего не нужно). Каждому ученику нужны устройство и интернет. Аккаунт Google не нужен.","source":"Информатика, учебник 9 класса, глава 2, с. 30–31. Урок намеренно отходит от учебника: вместо Google Forms каждая тема выполняется параллельно в таблице и в SQL. Все запросы и ответы проверены выполнением, данные учебные.","stages":["Отвечает на два вопроса об INSERT и SELECT","Изучает фильтр и сортировку, запись WHERE и ORDER BY","Вместе с учителем выводит книги с количеством больше 5 по убыванию","Считает по условию в таблице и пишет два запроса в SQL; кто успел — запрос ★","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"Finding what you need in a lot of data: filtering (choosing by a condition) and sorting (putting in order). COUNTIF in a sheet, WHERE and ORDER BY in SQL.","objectives":["Explain the difference between filtering and sorting","Choose records with a WHERE condition","Show the result in ascending or descending order with ORDER BY"],"prior":"Can write SELECT and INSERT; know COUNT, MIN and MAX in a sheet (lesson 2.3, Grade 8).","env":"The ClassFlow sheet and the ClassFlow SQL editor (in the browser, nothing to install). One device per student and the internet. No Google account is needed.","source":"Informatics, Grade 9 textbook, chapter 2, pp. 30–31. The lesson leaves the textbook on purpose: instead of Google Forms every topic is done side by side in a sheet and in SQL. Every query and answer was run; the data are made for the classroom.","stages":["Answers two questions about INSERT and SELECT","Learns filtering and sorting, and how WHERE and ORDER BY are written","Shows the books with more than 5 copies in descending order with the teacher","Counts by a condition in a sheet and writes two SQL queries; fast students take the ★ query","Takes a short test and says what was learned"]}}$s9$::jsonb, $s9$[{"term":"filter","definition":"Сүзгі — шартқа сәйкес жазбаларды ғана көрсету · Фильтр — показ только записей, подходящих под условие · Filter — showing only the records that meet a condition"},{"term":"sort","definition":"Сұрыптау — жазбаларды бір өріс бойынша ретке келтіру · Сортировка — упорядочение записей по одному полю · Sort — putting the records in order by one field"},{"term":"WHERE","definition":"WHERE — SQL-дегі шарт: тек сәйкес жазбалар шығады · WHERE — условие в SQL: выходят только подходящие записи · WHERE — a condition in SQL: only matching records are returned"},{"term":"ORDER BY","definition":"ORDER BY — нәтижені сұрыптау; ASC — өсу, DESC — кему ретімен · ORDER BY — сортировка результата; ASC — по возрастанию, DESC — по убыванию · ORDER BY — sorts the result; ASC ascending, DESC descending"}]$s9$::jsonb, $s9$[{"type":"title","pageType":"slide","templateId":"title","title":"2.4 Деректерді сұрыптау және сүзу","subtitle":"Информатика 9-сынып · 2-тарау «Деректер қоры» · оқулық 30–31-б.","ru":{"title":"2.4 Сортировка и фильтрация данных","subtitle":"Информатика 9 класс · глава 2 «Базы данных» · учебник, с. 30–31"},"en":{"title":"2.4 Sorting and filtering data","subtitle":"Informatics Grade 9 · Chapter 2 “Databases” · textbook pp. 30–31"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: INSERT","prompt":"INSERT INTO командасы не істейді?","options":["Кестені көрсетеді","Кестеге жаңа жазба қосады","Жаңа кесте жасайды","Жазбаларды сұрыптайды"],"answer":1,"explanation":"INSERT INTO — жаңа жазба қосу.","points":1,"ru":{"title":"Повторение: INSERT","prompt":"Что делает команда INSERT INTO?","options":["Показывает таблицу","Добавляет в таблицу новую запись","Создаёт новую таблицу","Сортирует записи"],"explanation":"INSERT INTO — добавление новой записи.","notes":"5 минут. Вопрос: «Если в библиотеке 5000 книг, как быстро найти нужную?»"},"en":{"title":"Review: INSERT","prompt":"What does INSERT INTO do?","options":["Shows a table","Adds a new record to a table","Makes a new table","Sorts the records"],"explanation":"INSERT INTO adds a new record.","notes":"5 minutes. Ask: “If a library has 5000 books, how do we find the right one quickly?”"},"stage":"warmup","notes":"5 минут. Сұрақ: «Кітапханада 5000 кітап болса, керегін қалай тез табамыз?»"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: жұлдызша","prompt":"SELECT * FROM books; сұранысындағы * нені білдіреді?","options":["Барлық өрістер","Көбейту","Бірінші жазба","Маңызды кітаптар"],"answer":0,"explanation":"* — «барлық өрістер».","points":1,"ru":{"title":"Повторение: звёздочка","prompt":"Что означает * в запросе SELECT * FROM books;?","options":["Все поля","Умножение","Первая запись","Важные книги"],"explanation":"* — «все поля»."},"en":{"title":"Review: the star","prompt":"What does * mean in SELECT * FROM books;?","options":["All fields","Multiplication","The first record","Important books"],"explanation":"* means “all fields”."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Сүзу: кестеде және SQL-де","bullets":["Сүзгі тек шартқа сәйкес жазбаларды қалдырады. Google Sheets-те: Data → Create a filter.","ClassFlow кестесінде сүзгі батырмасы жоқ, сондықтан шартқа сәйкес жазбаларды COUNTIF функциясымен санаймыз.","SQL-де шарт WHERE сөзінен кейін жазылады. Белгілер: = тең, <> тең емес, > үлкен, < кіші, >= және <=. Мәтін тырнақшада."],"code":"SELECT title, qty FROM books WHERE qty > 5;\nSELECT title FROM books WHERE genre = 'Classical';","lang":"text","ru":{"title":"Фильтр: в таблице и в SQL","bullets":["Фильтр оставляет только записи, подходящие под условие. В Google Sheets: Data → Create a filter.","В таблице ClassFlow кнопки фильтра нет, поэтому записи по условию считаем функцией COUNTIF.","В SQL условие пишут после слова WHERE. Знаки: = равно, <> не равно, > больше, < меньше, >= и <=. Текст в кавычках."],"notes":"8 минут (два слайда). Фильтр уменьшает число записей, сортировка меняет только порядок. Спросите учеников об этой разнице."},"en":{"title":"Filtering: in a sheet and in SQL","bullets":["A filter keeps only the records that meet a condition. In Google Sheets: Data → Create a filter.","The ClassFlow sheet has no filter button, so we count the matching records with COUNTIF.","In SQL the condition follows the word WHERE. Signs: = equal, <> not equal, > greater, < less, >= and <=. Text goes in quotes."],"notes":"8 minutes (two slides). Filtering removes records, sorting only changes the order. Ask the students about the difference."},"stage":"together","notes":"8 минут (екі слайд). Сүзу — жазбаларды азайтады, сұрыптау — тек ретін өзгертеді. Осы айырманы оқушылардан сұраңыз.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Сұрыптау: ORDER BY","bullets":["Сұрыптау жазбаларды бір өріс бойынша ретке келтіреді: әліпби бойынша немесе сан бойынша.","SQL-де: ORDER BY өріс. ASC — өсу ретімен (әдепкі), DESC — кему ретімен.","WHERE мен ORDER BY бірге жазылса, алдымен WHERE, сосын ORDER BY тұрады."],"code":"SELECT title, year FROM books ORDER BY year;\nSELECT title, qty FROM books WHERE qty > 5 ORDER BY qty DESC;","lang":"text","ru":{"title":"Сортировка: ORDER BY","bullets":["Сортировка упорядочивает записи по одному полю: по алфавиту или по числу.","В SQL: ORDER BY поле. ASC — по возрастанию (по умолчанию), DESC — по убыванию.","Если WHERE и ORDER BY пишут вместе, сначала идёт WHERE, потом ORDER BY."]},"en":{"title":"Sorting: ORDER BY","bullets":["Sorting puts the records in order by one field: alphabetically or by number.","In SQL: ORDER BY field. ASC is ascending (the default), DESC descending.","When WHERE and ORDER BY are used together, WHERE comes first."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: саны көп кітаптар","bullets":["«Орындау» бас: саны 5-тен көп кітаптар кему ретімен шығады. Неше жазба шықты?","DESC сөзін өшіріп, қайта орында: реті қалай өзгерді?","Шартты qty >= 5 деп өзгерт: қай кітап қосылды?"],"code":"SELECT title, qty FROM books WHERE qty > 5 ORDER BY qty DESC;","lang":"sql","sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"SELECT title, qty FROM books WHERE qty > 5 ORDER BY qty DESC;"},"notes":"10 минут. qty > 5: бес жазба (10, 9, 8, 7, 6). qty >= 5 болса «Шерлок Холмс» (5) қосылады — алты жазба. «>» мен «>=» айырмасына назар аударыңыз.","ru":{"title":"Пример: книги с большим количеством","bullets":["Нажми «Выполнить»: выйдут книги с количеством больше 5 по убыванию. Сколько записей?","Удали слово DESC и выполни снова: как изменился порядок?","Измени условие на qty >= 5: какая книга добавилась?"],"notes":"10 минут. qty > 5: пять записей (10, 9, 8, 7, 6). При qty >= 5 добавится «Шерлок Холмс» (5) — шесть записей. Обратите внимание на разницу «>» и «>=»."},"en":{"title":"Example: the books with many copies","bullets":["Press “Run”: the books with more than 5 copies appear in descending order. How many records?","Delete the word DESC and run again: how did the order change?","Change the condition to qty >= 5: which book was added?"],"notes":"10 minutes. qty > 5 gives five records (10, 9, 8, 7, 6). With qty >= 5 “Шерлок Холмс” (5) joins: six records. Point out the difference between “>” and “>=”."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 1: кестеде шарт бойынша санау","prompt":"Кітапхана кестесі дайын. Сары ұяшықтарды формуламен есепте: саны 5-тен көп кітаптар нешеу, Adventure жанрында нешеу, ең жаңа кітап қай жылы шыққан?","points":6,"picture":"lec/inf8-g9-filter-kk.svg","pictureAlt":"Сегіз кітаптың кестесі; шарт бойынша екі сан және ең жаңа жыл бос","sheet":{"rows":14,"cols":6,"cells":{"A1":"Атауы","B1":"Жанры","C1":"Жылы","D1":"Саны","E1":"Рейтингі","A2":"Абай жолы","B2":"Classical","C2":"1942","D2":"10","E2":"5","A3":"Қан мен тер","B3":"Classical","C3":"1970","D3":"4","E3":"4","A4":"Көшпенділер","B4":"History","C4":"1976","D4":"6","E4":"5","A5":"Менің атым Қожа","B5":"Adventure","C5":"1957","D5":"8","E5":"5","A6":"Шерлок Холмс","B6":"Detective","C6":"1892","D6":"5","E6":"5","A7":"Соғыс және бейбітшілік","B7":"Classical","C7":"1869","D7":"3","E7":"4","A8":"Алиса ғажайыптар елінде","B8":"Adventure","C8":"1865","D8":"7","E8":"4","A9":"Алхимик","B9":"Adventure","C9":"1988","D9":"9","E9":"3","A11":"Саны 5-тен көп","A12":"Adventure жанры","A13":"Ең жаңа жыл"}},"criteria":[{"id":"c1","text":"D11 — саны 5-тен көп кітаптар (COUNTIF)","cell":"D11","points":2,"fn":"COUNTIF","accept":["5"]},{"id":"c2","text":"D12 — Adventure жанрындағы кітаптар (COUNTIF)","cell":"D12","points":2,"fn":"COUNTIF","accept":["3"]},{"id":"c3","text":"★ C13 — ең жаңа кітаптың жылы (MAX)","cell":"C13","points":2,"fn":"MAX","accept":["1988"]}],"steps":["Көмек: D11 ұяшығына =COUNTIF(D2:D9;\">5\") жаз.","D12: шарт мәтін болса, тырнақшада жазылады: \"Adventure\".","★ C13: ең үлкен жылды MAX функциясымен тап."],"notes":"15 минут (төрт тапсырма). Күтілетін нәтиже: D11 = 5, D12 = 3, C13 = 1988. Кесте алдын ала толтырылған, оқушы тек формула жазады.","ru":{"title":"Практика 1: считаем по условию в таблице","prompt":"Таблица библиотеки готова. Посчитай жёлтые ячейки формулами: сколько книг с количеством больше 5, сколько в жанре Adventure, какого года самая новая книга?","picture":"lec/inf8-g9-filter-ru.svg","pictureAlt":"Таблица из восьми книг; два счёта по условию и самый новый год пустые","criteria":[{"id":"c1","text":"D11 — книги с количеством больше 5 (COUNTIF)","cell":"D11","points":2,"fn":"COUNTIF"},{"id":"c2","text":"D12 — книги жанра Adventure (COUNTIF)","cell":"D12","points":2,"fn":"COUNTIF"},{"id":"c3","text":"★ C13 — год самой новой книги (MAX)","cell":"C13","points":2,"fn":"MAX"}],"steps":["Подсказка: в D11 запиши =COUNTIF(D2:D9;\">5\").","D12: условие-текст пишут в кавычках: \"Adventure\".","★ C13: найди наибольший год функцией MAX."],"notes":"15 минут (четыре задания). Ожидаемый результат: D11 = 5, D12 = 3, C13 = 1988. Таблица уже заполнена, ученик пишет только формулы.","sheet":{"rows":14,"cols":6,"cells":{"A1":"Название","B1":"Жанр","C1":"Год","D1":"Кол-во","E1":"Рейтинг","A2":"Абай жолы","B2":"Classical","C2":"1942","D2":"10","E2":"5","A3":"Қан мен тер","B3":"Classical","C3":"1970","D3":"4","E3":"4","A4":"Көшпенділер","B4":"History","C4":"1976","D4":"6","E4":"5","A5":"Менің атым Қожа","B5":"Adventure","C5":"1957","D5":"8","E5":"5","A6":"Шерлок Холмс","B6":"Detective","C6":"1892","D6":"5","E6":"5","A7":"Соғыс және бейбітшілік","B7":"Classical","C7":"1869","D7":"3","E7":"4","A8":"Алиса ғажайыптар елінде","B8":"Adventure","C8":"1865","D8":"7","E8":"4","A9":"Алхимик","B9":"Adventure","C9":"1988","D9":"9","E9":"3","A11":"Количество больше 5","A12":"Жанр Adventure","A13":"Самый новый год"}}},"en":{"title":"Practice 1: counting by a condition in a sheet","prompt":"The library sheet is ready. Work out the yellow cells with formulas: how many books have more than 5 copies, how many are Adventure, and which year is the newest book?","picture":"lec/inf8-g9-filter-en.svg","pictureAlt":"A table of eight books; two conditional counts and the newest year are empty","criteria":[{"id":"c1","text":"D11 — books with more than 5 copies (COUNTIF)","cell":"D11","points":2,"fn":"COUNTIF"},{"id":"c2","text":"D12 — Adventure books (COUNTIF)","cell":"D12","points":2,"fn":"COUNTIF"},{"id":"c3","text":"★ C13 — the year of the newest book (MAX)","cell":"C13","points":2,"fn":"MAX"}],"steps":["Hint: in D11 type =COUNTIF(D2:D9;\">5\").","D12: a text condition goes in quotes: \"Adventure\".","★ C13: find the largest year with MAX."],"notes":"15 minutes (four tasks). Expected: D11 = 5, D12 = 3, C13 = 1988. The sheet is prefilled; the student only writes formulas.","sheet":{"rows":14,"cols":6,"cells":{"A1":"Title","B1":"Genre","C1":"Year","D1":"Qty","E1":"Rating","A2":"Абай жолы","B2":"Classical","C2":"1942","D2":"10","E2":"5","A3":"Қан мен тер","B3":"Classical","C3":"1970","D3":"4","E3":"4","A4":"Көшпенділер","B4":"History","C4":"1976","D4":"6","E4":"5","A5":"Менің атым Қожа","B5":"Adventure","C5":"1957","D5":"8","E5":"5","A6":"Шерлок Холмс","B6":"Detective","C6":"1892","D6":"5","E6":"5","A7":"Соғыс және бейбітшілік","B7":"Classical","C7":"1869","D7":"3","E7":"4","A8":"Алиса ғажайыптар елінде","B8":"Adventure","C8":"1865","D8":"7","E8":"4","A9":"Алхимик","B9":"Adventure","C9":"1988","D9":"9","E9":"3","A11":"More than 5 copies","A12":"Adventure genre","A13":"Newest year"}}},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["69f3cda0"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","rows":4},"title":"Практика 2: рейтингі 5 кітаптар","prompt":"Рейтингі (rating) 5-ке тең кітаптардың атауы (title) мен авторын (author) көрсет.","notes":"Дұрыс сұраныс: SELECT title, author FROM books WHERE rating = 5; Төрт жазба шығады.","ru":{"title":"Практика 2: книги с рейтингом 5","prompt":"Покажи название (title) и автора (author) книг, у которых рейтинг (rating) равен 5.","notes":"Верный запрос: SELECT title, author FROM books WHERE rating = 5; Выйдут четыре записи."},"en":{"title":"Practice 2: the books rated 5","prompt":"Show the title and the author of the books whose rating is 5.","notes":"Correct query: SELECT title, author FROM books WHERE rating = 5; Four records."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["e46a17bf"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","ordered":true,"rows":8},"title":"Практика 3: ескіден жаңаға","prompt":"Барлық кітаптың атауы (title) мен жылын (year) ескі кітаптан жаңасына қарай ретімен көрсет.","notes":"Мұнда жолдардың реті де тексеріледі. Дұрыс сұраныс: SELECT title, year FROM books ORDER BY year;","ru":{"title":"Практика 3: от старых к новым","prompt":"Покажи название (title) и год (year) всех книг в порядке от самой старой к самой новой.","notes":"Здесь проверяется и порядок строк. Верный запрос: SELECT title, year FROM books ORDER BY year;"},"en":{"title":"Practice 3: from old to new","prompt":"Show the title and the year of every book from the oldest to the newest.","notes":"The row order is checked here too. Correct query: SELECT title, year FROM books ORDER BY year;"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":3,"accept":["543c761f"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","ordered":true,"rows":2},"title":"★ Күрделі: екі шарт","prompt":"Adventure жанрындағы және рейтингі 4-тен кем емес кітаптардың атауы (title) мен санын (qty) саны көбінен азына қарай көрсет. Көмек: екі шартты AND сөзімен байланыстыр.","notes":"Жылдам оқушыларға. «Алхимик» Adventure жанрында, бірақ рейтингі 3 — шартқа сәйкес емес. Екі жазба шығады.","ru":{"title":"★ Сложнее: два условия","prompt":"Покажи название (title) и количество (qty) книг жанра Adventure с рейтингом не ниже 4, от большего количества к меньшему. Подсказка: два условия соединяет AND.","notes":"Для быстрых учеников. «Алхимик» — жанр Adventure, но рейтинг 3 — под условие не подходит. Выйдут две записи."},"en":{"title":"★ Harder: two conditions","prompt":"Show the title and the quantity of the Adventure books rated at least 4, from the largest quantity to the smallest. Hint: join two conditions with AND.","notes":"For fast students. “Алхимик” is Adventure but rated 3, so it does not match. Two records."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Сүзу ме, сұрыптау ма?","prompt":"Сүзу мен сұрыптаудың айырмасы қандай?","options":["Айырмасы жоқ","Сүзу ретін өзгертеді, сұрыптау жазбаларды өшіреді","Екеуі де жаңа жазба қосады","Сүзу шартқа сәйкес жазбаларды қалдырады, сұрыптау ретін өзгертеді"],"answer":3,"explanation":"Сүзу — таңдау (WHERE), сұрыптау — ретке келтіру (ORDER BY).","points":1,"ru":{"title":"Фильтр или сортировка?","prompt":"В чём разница между фильтром и сортировкой?","options":["Разницы нет","Фильтр меняет порядок, сортировка удаляет записи","Оба добавляют новые записи","Фильтр оставляет записи по условию, сортировка меняет порядок"],"explanation":"Фильтр — отбор (WHERE), сортировка — упорядочение (ORDER BY).","notes":"7 минут: два вопроса и итог."},"en":{"title":"Filter or sort?","prompt":"What is the difference between filtering and sorting?","options":["There is none","Filtering changes the order, sorting deletes records","Both add new records","Filtering keeps the matching records, sorting changes the order"],"explanation":"Filtering chooses (WHERE), sorting orders (ORDER BY).","notes":"7 minutes: two questions and the wrap-up."},"stage":"check","notes":"7 минут: екі сұрақ және қорытынды."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"DESC","prompt":"ORDER BY qty DESC нәтижені қалай шығарады?","options":["Саны азынан көбіне қарай","Саны көбінен азына қарай","Әліпби ретімен","Кездейсоқ ретпен"],"answer":1,"explanation":"DESC — кему ретімен: ең үлкен мән бірінші тұрады.","points":1,"ru":{"title":"DESC","prompt":"Как выводит результат ORDER BY qty DESC?","options":["От меньшего количества к большему","От большего количества к меньшему","По алфавиту","В случайном порядке"],"explanation":"DESC — по убыванию: наибольшее значение идёт первым."},"en":{"title":"DESC","prompt":"How does ORDER BY qty DESC arrange the result?","options":["From the smallest quantity to the largest","From the largest quantity to the smallest","Alphabetically","In a random order"],"explanation":"DESC is descending: the largest value comes first."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s9$::jsonb),
    ($s9$2.5 Жиынтық кесте$s9$, $s9$Информатика$s9$, 4, $s9${"summary":"Жазбаларды бір өріс бойынша топтап, әр топты қорытындылау. Кестеде SUMIF және COUNTIF, SQL-де GROUP BY, SUM, COUNT, MAX.","objectives":["Жиынтық кестенің не үшін керегін түсіндіру","Кестеде топ бойынша қосындыны SUMIF көмегімен табу","GROUP BY және SUM, COUNT функцияларымен есеп жасау"],"grade":9,"duration":"45 минут","prior":"WHERE және ORDER BY жаза алады; кестеде COUNTIF қолдана алады (2.4 сабақ).","env":"ClassFlow кестесі және ClassFlow SQL редакторы (браузерде, орнату керек емес). Әр оқушыға бір құрылғы және интернет қажет. Google аккаунты керек емес.","source":"Информатика, 9-сынып оқулығы, 2-тарау, 32–33 беттер. Сабақ оқулықтан әдейі ауытқиды: Google Forms орнына әр тақырып кестеде және SQL-де қатар орындалады. Барлық сұраныстар мен жауаптар орындалып тексерілген, деректер оқу үшін құрастырылған.","stages":[{"k":"warmup","min":5,"do":"WHERE және ORDER BY туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Жиынтық кестенің идеясын және GROUP BY жазылуын үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге әр жанрдағы кітаптардың жалпы санын шығарады"},{"k":"practice","min":15,"do":"Кестеде жанр бойынша қорытынды жасайды, SQL-де екі есеп жазады; үлгерген оқушы ★ сұранысты орындайды"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Группировка записей по одному полю и итог по каждой группе. В таблице — SUMIF и COUNTIF, в SQL — GROUP BY, SUM, COUNT, MAX.","objectives":["Объяснять, зачем нужна сводная таблица","Находить сумму по группе в таблице функцией SUMIF","Строить отчёт с GROUP BY и функциями SUM, COUNT"],"prior":"Умеют писать WHERE и ORDER BY; применяют COUNTIF в таблице (урок 2.4).","env":"Таблица ClassFlow и SQL-редактор ClassFlow (в браузере, устанавливать ничего не нужно). Каждому ученику нужны устройство и интернет. Аккаунт Google не нужен.","source":"Информатика, учебник 9 класса, глава 2, с. 32–33. Урок намеренно отходит от учебника: вместо Google Forms каждая тема выполняется параллельно в таблице и в SQL. Все запросы и ответы проверены выполнением, данные учебные.","stages":["Отвечает на два вопроса о WHERE и ORDER BY","Изучает идею сводной таблицы и запись GROUP BY","Вместе с учителем выводит общее количество книг каждого жанра","Делает итог по жанрам в таблице и два отчёта в SQL; кто успел — запрос ★","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"Grouping records by one field and summarising each group. SUMIF and COUNTIF in a sheet; GROUP BY, SUM, COUNT, MAX in SQL.","objectives":["Explain what a pivot table is for","Find a group total in a sheet with SUMIF","Build a report with GROUP BY and the functions SUM and COUNT"],"prior":"Can write WHERE and ORDER BY; can use COUNTIF in a sheet (lesson 2.4).","env":"The ClassFlow sheet and the ClassFlow SQL editor (in the browser, nothing to install). One device per student and the internet. No Google account is needed.","source":"Informatics, Grade 9 textbook, chapter 2, pp. 32–33. The lesson leaves the textbook on purpose: instead of Google Forms every topic is done side by side in a sheet and in SQL. Every query and answer was run; the data are made for the classroom.","stages":["Answers two questions about WHERE and ORDER BY","Learns the idea of a pivot table and how GROUP BY is written","Shows the total copies of each genre with the teacher","Summarises by genre in a sheet and writes two SQL reports; fast students take the ★ query","Takes a short test and says what was learned"]}}$s9$::jsonb, $s9$[{"term":"pivot table","definition":"Жиынтық кесте — деректерді топтап, қорытындысын көрсететін кесте · Сводная таблица — таблица, которая группирует данные и показывает итоги · Pivot table — a table that groups data and shows the totals"},{"term":"GROUP BY","definition":"GROUP BY — жазбаларды бір өрістің мәні бойынша топтайды · GROUP BY — группирует записи по значению одного поля · GROUP BY — groups the records by the value of one field"},{"term":"SUM","definition":"SUM — топтағы сандардың қосындысы · SUM — сумма чисел в группе · SUM — the total of the numbers in a group"},{"term":"COUNT","definition":"COUNT(*) — топтағы жазбалар саны · COUNT(*) — число записей в группе · COUNT(*) — the number of records in a group"}]$s9$::jsonb, $s9$[{"type":"title","pageType":"slide","templateId":"title","title":"2.5 Жиынтық кесте","subtitle":"Информатика 9-сынып · 2-тарау «Деректер қоры» · оқулық 32–33-б.","ru":{"title":"2.5 Сводная таблица","subtitle":"Информатика 9 класс · глава 2 «Базы данных» · учебник, с. 32–33"},"en":{"title":"2.5 Pivot table","subtitle":"Informatics Grade 9 · Chapter 2 “Databases” · textbook pp. 32–33"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: WHERE","prompt":"SELECT title FROM books WHERE qty > 5; сұранысы нені шығарады?","options":["Барлық кітаптың атауын","Алғашқы бес кітапты","Саны 5-тен көп кітаптардың атауын","Саны 5-ке тең кітаптарды"],"answer":2,"explanation":"WHERE тек шартқа сәйкес жазбаларды қалдырады.","points":1,"ru":{"title":"Повторение: WHERE","prompt":"Что выведет запрос SELECT title FROM books WHERE qty > 5;?","options":["Названия всех книг","Первые пять книг","Названия книг с количеством больше 5","Книги с количеством, равным 5"],"explanation":"WHERE оставляет только записи, подходящие под условие.","notes":"5 минут. Вопрос: «Как быстро узнать, сколько в библиотеке книг каждого жанра?»"},"en":{"title":"Review: WHERE","prompt":"What does SELECT title FROM books WHERE qty > 5; return?","options":["The titles of all books","The first five books","The titles of the books with more than 5 copies","The books with exactly 5 copies"],"explanation":"WHERE keeps only the records that meet the condition.","notes":"5 minutes. Ask: “How can we quickly find how many books of each genre the library has?”"},"stage":"warmup","notes":"5 минут. Сұрақ: «Кітапханада әр жанрда қанша кітап бар екенін қалай тез білеміз?»"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: COUNTIF","prompt":"=COUNTIF(B2:B9;\"Adventure\") формуласы не істейді?","options":["B2:B9 ішінде «Adventure» жазылған ұяшықтарды санайды","B2:B9 сандарын қосады","«Adventure» сөзін барлық ұяшыққа жазады","Ең ұзын сөзді табады"],"answer":0,"explanation":"COUNTIF шартқа сәйкес ұяшықтарды санайды.","points":1,"ru":{"title":"Повторение: COUNTIF","prompt":"Что делает формула =COUNTIF(B2:B9;\"Adventure\")?","options":["Считает ячейки B2:B9 со словом «Adventure»","Складывает числа B2:B9","Записывает «Adventure» во все ячейки","Находит самое длинное слово"],"explanation":"COUNTIF считает ячейки, подходящие под условие."},"en":{"title":"Review: COUNTIF","prompt":"What does =COUNTIF(B2:B9;\"Adventure\") do?","options":["Counts the cells in B2:B9 that hold “Adventure”","Adds the numbers in B2:B9","Types “Adventure” into every cell","Finds the longest word"],"explanation":"COUNTIF counts the cells that meet a condition."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Жиынтық кесте деген не?","bullets":["Жиынтық кесте жазбаларды бір өріс бойынша топтайды да, әр топтың қорытындысын көрсетеді: қосындысын немесе санын.","Мысалы: 8 кітап → 4 жанр. Әр жанрда неше дана бар? Google Sheets-те: Data → Pivot table, Rows: Genre, Values: SUM of Quantity.","ClassFlow кестесінде осы қорытындыны SUMIF (топ қосындысы) және COUNTIF (топтағы саны) функцияларымен жасаймыз."],"code":"=SUMIF(B2:B9;\"Classical\";D2:D9)\n=COUNTIF(B2:B9;\"Classical\")","lang":"text","ru":{"title":"Что такое сводная таблица?","bullets":["Сводная таблица группирует записи по одному полю и показывает итог каждой группы: сумму или количество.","Например: 8 книг → 4 жанра. Сколько штук в каждом жанре? В Google Sheets: Data → Pivot table, Rows: Genre, Values: SUM of Quantity.","В таблице ClassFlow тот же итог делаем функциями SUMIF (сумма группы) и COUNTIF (число в группе)."],"notes":"8 минут (два слайда). Покажите вручную на доске: три книги жанра Classical — 10 + 4 + 3 = 17. SUMIF делает именно это."},"en":{"title":"What is a pivot table?","bullets":["A pivot table groups the records by one field and shows a summary of each group: a total or a count.","For example: 8 books make 4 genres. How many copies in each? In Google Sheets: Data → Pivot table, Rows: Genre, Values: SUM of Quantity.","In the ClassFlow sheet we build the same summary with SUMIF (group total) and COUNTIF (group count)."],"notes":"8 minutes (two slides). Show by hand on the board: the three Classical books make 10 + 4 + 3 = 17. SUMIF does exactly this."},"stage":"together","notes":"8 минут (екі слайд). Тақтада қолмен көрсетіңіз: Classical жанрындағы үш кітаптың саны 10 + 4 + 3 = 17. SUMIF дәл осыны жасайды.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"SQL-де топтау: GROUP BY","bullets":["GROUP BY өріс — жазбаларды сол өрістің мәні бойынша топтарға бөледі.","Топқа функция қолданылады: SUM — қосынды, COUNT(*) — жазбалар саны, AVG — орташа, MIN және MAX — ең кіші және ең үлкен.","Нәтижеде әр топқа бір жол шығады: 4 жанр — 4 жол."],"code":"SELECT genre, SUM(qty) FROM books GROUP BY genre;\nSELECT genre, COUNT(*) FROM books GROUP BY genre;","lang":"text","ru":{"title":"Группировка в SQL: GROUP BY","bullets":["GROUP BY поле — делит записи на группы по значению этого поля.","К группе применяют функцию: SUM — сумма, COUNT(*) — число записей, AVG — среднее, MIN и MAX — наименьшее и наибольшее.","В результате на каждую группу одна строка: 4 жанра — 4 строки."]},"en":{"title":"Grouping in SQL: GROUP BY","bullets":["GROUP BY field splits the records into groups by the value of that field.","A function is applied to each group: SUM total, COUNT(*) number of records, AVG mean, MIN and MAX smallest and largest.","The result has one row per group: 4 genres make 4 rows."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: жанр бойынша жалпы сан","bullets":["«Орындау» бас: әр жанрға бір жол шығады. Classical жанрында неше дана бар?","SUM(qty) орнына COUNT(*) жаз: енді әр жанрдағы кітап атауларының саны шығады.","GROUP BY genre бөлігін өшіріп, SELECT SUM(qty) FROM books; орында: бүкіл кітапхананың жалпы саны шығады."],"code":"SELECT genre, SUM(qty) FROM books GROUP BY genre;","lang":"sql","sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"SELECT genre, SUM(qty) FROM books GROUP BY genre;"},"notes":"10 минут. Нәтиже: Adventure 24, Classical 17, Detective 5, History 6; барлығы 52. COUNT(*): 3, 3, 1, 1. Қосынды мен санның айырмасын сұраңыз: 3 атау, бірақ 17 дана.","ru":{"title":"Пример: общее количество по жанрам","bullets":["Нажми «Выполнить»: на каждый жанр одна строка. Сколько штук в жанре Classical?","Замени SUM(qty) на COUNT(*): теперь выйдет число названий в каждом жанре.","Удали GROUP BY genre и выполни SELECT SUM(qty) FROM books;: выйдет общее количество по всей библиотеке."],"notes":"10 минут. Результат: Adventure 24, Classical 17, Detective 5, History 6; всего 52. COUNT(*): 3, 3, 1, 1. Спросите о разнице суммы и количества: 3 названия, но 17 штук."},"en":{"title":"Example: total copies by genre","bullets":["Press “Run”: one row per genre. How many copies does Classical have?","Replace SUM(qty) with COUNT(*): now you get the number of titles in each genre.","Remove GROUP BY genre and run SELECT SUM(qty) FROM books;: the total for the whole library."],"notes":"10 minutes. Result: Adventure 24, Classical 17, Detective 5, History 6; 52 in all. COUNT(*): 3, 3, 1, 1. Ask about total versus count: 3 titles but 17 copies."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 1: кестеде жанр бойынша қорытынды","prompt":"Кітапхана кестесінің астында қорытынды кесте бар. Әр жанрдағы кітаптардың жалпы санын (B бағаны) және барлығын формуламен есепте.","points":9,"picture":"lec/inf8-g9-pivot-kk.svg","pictureAlt":"Сегіз кітаптың кестесі және төрт жанрдың қорытынды кестесі; жалпы сандар бос","sheet":{"rows":17,"cols":6,"cells":{"A1":"Атауы","B1":"Жанры","C1":"Жылы","D1":"Саны","E1":"Рейтингі","A2":"Абай жолы","B2":"Classical","C2":"1942","D2":"10","E2":"5","A3":"Қан мен тер","B3":"Classical","C3":"1970","D3":"4","E3":"4","A4":"Көшпенділер","B4":"History","C4":"1976","D4":"6","E4":"5","A5":"Менің атым Қожа","B5":"Adventure","C5":"1957","D5":"8","E5":"5","A6":"Шерлок Холмс","B6":"Detective","C6":"1892","D6":"5","E6":"5","A7":"Соғыс және бейбітшілік","B7":"Classical","C7":"1869","D7":"3","E7":"4","A8":"Алиса ғажайыптар елінде","B8":"Adventure","C8":"1865","D8":"7","E8":"4","A9":"Алхимик","B9":"Adventure","C9":"1988","D9":"9","E9":"3","A11":"Жанр","B11":"Жалпы саны","C11":"Кітап саны","A12":"Classical","A13":"History","A14":"Adventure","A15":"Detective","A16":"Барлығы"}},"criteria":[{"id":"c1","text":"B12 — Classical жанрының жалпы саны (SUMIF)","cell":"B12","points":2,"fn":"SUMIF","accept":["17"]},{"id":"c2","text":"B14 — Adventure жанрының жалпы саны (SUMIF)","cell":"B14","points":2,"fn":"SUMIF","accept":["24"]},{"id":"c3","text":"B13 және B15 — History мен Detective","cell":"B15","points":1,"fn":"SUMIF","accept":["5"]},{"id":"c4","text":"B16 — барлық жанрдың қосындысы (SUM)","cell":"B16","points":2,"fn":"SUM","accept":["52"]},{"id":"c5","text":"★ C12 — Classical жанрындағы кітап атауларының саны (COUNTIF)","cell":"C12","points":2,"fn":"COUNTIF","accept":["3"]}],"steps":["Көмек: B12 ұяшығына =SUMIF(B2:B9;\"Classical\";D2:D9) жаз: B бағанында жанрды іздейді, D бағанындағы санды қосады.","B13–B15 үшін жанр атын ғана өзгерт. B16-ға =SUM(B12:B15) жаз.","★ C12: Classical жанрында неше кітап атауы бар? COUNTIF қолдан."],"notes":"15 минут (төрт тапсырма). Күтілетін нәтиже: B12 = 17, B13 = 6, B14 = 24, B15 = 5, B16 = 52, C12 = 3. Тексеру: B16 кітапхананың жалпы санына (52) тең болуы керек.","ru":{"title":"Практика 1: итог по жанрам в таблице","prompt":"Под таблицей библиотеки есть итоговая таблица. Формулами посчитай общее количество книг каждого жанра (столбец B) и общий итог.","picture":"lec/inf8-g9-pivot-ru.svg","pictureAlt":"Таблица из восьми книг и итоговая таблица четырёх жанров; итоги пустые","criteria":[{"id":"c1","text":"B12 — общее количество жанра Classical (SUMIF)","cell":"B12","points":2,"fn":"SUMIF"},{"id":"c2","text":"B14 — общее количество жанра Adventure (SUMIF)","cell":"B14","points":2,"fn":"SUMIF"},{"id":"c3","text":"B13 и B15 — History и Detective","cell":"B15","points":1,"fn":"SUMIF"},{"id":"c4","text":"B16 — сумма по всем жанрам (SUM)","cell":"B16","points":2,"fn":"SUM"},{"id":"c5","text":"★ C12 — число названий жанра Classical (COUNTIF)","cell":"C12","points":2,"fn":"COUNTIF"}],"steps":["Подсказка: в B12 запиши =SUMIF(B2:B9;\"Classical\";D2:D9): ищет жанр в столбце B, складывает количество из столбца D.","Для B13–B15 меняй только название жанра. В B16 запиши =SUM(B12:B15).","★ C12: сколько названий в жанре Classical? Используй COUNTIF."],"notes":"15 минут (четыре задания). Ожидаемый результат: B12 = 17, B13 = 6, B14 = 24, B15 = 5, B16 = 52, C12 = 3. Проверка: B16 должно равняться общему количеству книг (52).","sheet":{"rows":17,"cols":6,"cells":{"A1":"Название","B1":"Жанр","C1":"Год","D1":"Кол-во","E1":"Рейтинг","A2":"Абай жолы","B2":"Classical","C2":"1942","D2":"10","E2":"5","A3":"Қан мен тер","B3":"Classical","C3":"1970","D3":"4","E3":"4","A4":"Көшпенділер","B4":"History","C4":"1976","D4":"6","E4":"5","A5":"Менің атым Қожа","B5":"Adventure","C5":"1957","D5":"8","E5":"5","A6":"Шерлок Холмс","B6":"Detective","C6":"1892","D6":"5","E6":"5","A7":"Соғыс және бейбітшілік","B7":"Classical","C7":"1869","D7":"3","E7":"4","A8":"Алиса ғажайыптар елінде","B8":"Adventure","C8":"1865","D8":"7","E8":"4","A9":"Алхимик","B9":"Adventure","C9":"1988","D9":"9","E9":"3","A11":"Жанр","B11":"Всего штук","C11":"Число книг","A12":"Classical","A13":"History","A14":"Adventure","A15":"Detective","A16":"Всего"}}},"en":{"title":"Practice 1: a summary by genre in a sheet","prompt":"Below the library sheet there is a summary table. With formulas work out the total copies of each genre (column B) and the grand total.","picture":"lec/inf8-g9-pivot-en.svg","pictureAlt":"A table of eight books and a summary table of four genres; the totals are empty","criteria":[{"id":"c1","text":"B12 — total copies of Classical (SUMIF)","cell":"B12","points":2,"fn":"SUMIF"},{"id":"c2","text":"B14 — total copies of Adventure (SUMIF)","cell":"B14","points":2,"fn":"SUMIF"},{"id":"c3","text":"B13 and B15 — History and Detective","cell":"B15","points":1,"fn":"SUMIF"},{"id":"c4","text":"B16 — the total of all genres (SUM)","cell":"B16","points":2,"fn":"SUM"},{"id":"c5","text":"★ C12 — the number of Classical titles (COUNTIF)","cell":"C12","points":2,"fn":"COUNTIF"}],"steps":["Hint: in B12 type =SUMIF(B2:B9;\"Classical\";D2:D9): it looks for the genre in column B and adds the quantity from column D.","For B13–B15 change only the genre name. In B16 type =SUM(B12:B15).","★ C12: how many Classical titles are there? Use COUNTIF."],"notes":"15 minutes (four tasks). Expected: B12 = 17, B13 = 6, B14 = 24, B15 = 5, B16 = 52, C12 = 3. Check: B16 must equal the total number of copies (52).","sheet":{"rows":17,"cols":6,"cells":{"A1":"Title","B1":"Genre","C1":"Year","D1":"Qty","E1":"Rating","A2":"Абай жолы","B2":"Classical","C2":"1942","D2":"10","E2":"5","A3":"Қан мен тер","B3":"Classical","C3":"1970","D3":"4","E3":"4","A4":"Көшпенділер","B4":"History","C4":"1976","D4":"6","E4":"5","A5":"Менің атым Қожа","B5":"Adventure","C5":"1957","D5":"8","E5":"5","A6":"Шерлок Холмс","B6":"Detective","C6":"1892","D6":"5","E6":"5","A7":"Соғыс және бейбітшілік","B7":"Classical","C7":"1869","D7":"3","E7":"4","A8":"Алиса ғажайыптар елінде","B8":"Adventure","C8":"1865","D8":"7","E8":"4","A9":"Алхимик","B9":"Adventure","C9":"1988","D9":"9","E9":"3","A11":"Genre","B11":"Total copies","C11":"Books","A12":"Classical","A13":"History","A14":"Adventure","A15":"Detective","A16":"Total"}}},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["28fa346e"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","rows":4},"title":"Практика 2: жанр және жалпы сан","prompt":"Әр жанр (genre) үшін кітаптардың жалпы санын (qty қосындысы) көрсет: екі баған — жанр және қосынды.","notes":"Дұрыс сұраныс: SELECT genre, SUM(qty) FROM books GROUP BY genre; Нәтижесі кестедегі қорытындымен бірдей болуы керек.","ru":{"title":"Практика 2: жанр и общее количество","prompt":"Для каждого жанра (genre) покажи общее количество книг (сумму qty): два столбца — жанр и сумма.","notes":"Верный запрос: SELECT genre, SUM(qty) FROM books GROUP BY genre; Результат должен совпасть с итогом в таблице."},"en":{"title":"Practice 2: genre and total copies","prompt":"For each genre show the total number of copies (the sum of qty): two columns, the genre and the total.","notes":"Correct query: SELECT genre, SUM(qty) FROM books GROUP BY genre; The result must match the summary in the sheet."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["cad7e61b"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","rows":4},"title":"Практика 3: жанр және кітап саны","prompt":"Әр жанрда неше кітап атауы (жазба) бар? Екі баған: жанр және жазбалар саны.","notes":"Дұрыс сұраныс: SELECT genre, COUNT(*) FROM books GROUP BY genre;","ru":{"title":"Практика 3: жанр и число книг","prompt":"Сколько названий (записей) в каждом жанре? Два столбца: жанр и число записей.","notes":"Верный запрос: SELECT genre, COUNT(*) FROM books GROUP BY genre;"},"en":{"title":"Practice 3: genre and number of books","prompt":"How many titles (records) does each genre have? Two columns: the genre and the number of records.","notes":"Correct query: SELECT genre, COUNT(*) FROM books GROUP BY genre;"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":3,"accept":["0d1970c0"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","ordered":true,"rows":4},"title":"★ Күрделі: әр жанрдағы ең көп сан","prompt":"Әр жанр үшін ең көп дана саны бар кітаптың санын (MAX(qty)) көрсет. Нәтижені сол сан бойынша кему ретімен шығар. Екі баған: жанр және ең үлкен сан.","notes":"Жылдам оқушыларға. GROUP BY мен ORDER BY бірге: алдымен топтау, сосын сұрыптау. Мұнда жолдардың реті де тексеріледі.","ru":{"title":"★ Сложнее: наибольшее количество в жанре","prompt":"Для каждого жанра покажи наибольшее количество экземпляров одной книги (MAX(qty)). Результат выведи по убыванию этого числа. Два столбца: жанр и максимум.","notes":"Для быстрых учеников. GROUP BY вместе с ORDER BY: сначала группировка, потом сортировка. Здесь проверяется и порядок строк."},"en":{"title":"★ Harder: the largest quantity in each genre","prompt":"For each genre show the largest quantity of a single book (MAX(qty)). Order the result by that number, descending. Two columns: the genre and the maximum.","notes":"For fast students. GROUP BY with ORDER BY: grouping first, then sorting. The row order is checked too."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"GROUP BY","prompt":"GROUP BY genre не істейді?","options":["Жазбаларды жанр бойынша сұрыптайды","Жанры бос жазбаларды өшіреді","Жанр өрісін жасырады","Жанры бірдей жазбаларды бір топқа жинайды"],"answer":3,"explanation":"GROUP BY топтайды; әр топқа SUM, COUNT сияқты функция қолданылады.","points":1,"ru":{"title":"GROUP BY","prompt":"Что делает GROUP BY genre?","options":["Сортирует записи по жанру","Удаляет записи с пустым жанром","Скрывает поле жанра","Собирает записи с одинаковым жанром в одну группу"],"explanation":"GROUP BY группирует; к каждой группе применяют функцию вроде SUM или COUNT.","notes":"7 минут: два вопроса и итог."},"en":{"title":"GROUP BY","prompt":"What does GROUP BY genre do?","options":["Sorts the records by genre","Deletes the records with no genre","Hides the genre field","Puts the records with the same genre into one group"],"explanation":"GROUP BY groups; a function such as SUM or COUNT is applied to each group.","notes":"7 minutes: two questions and the wrap-up."},"stage":"check","notes":"7 минут: екі сұрақ және қорытынды."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"COUNT ма, SUM ба?","prompt":"Classical жанрында 3 кітап бар, даналары: 10, 4, 3. SUM(qty) мен COUNT(*) нені береді?","options":["SUM = 3, COUNT = 17","SUM = 17, COUNT = 3","Екеуі де 17","Екеуі де 3"],"answer":1,"explanation":"SUM мәндерді қосады (17), COUNT жазбаларды санайды (3).","points":1,"ru":{"title":"COUNT или SUM?","prompt":"В жанре Classical 3 книги с количеством 10, 4, 3. Что дадут SUM(qty) и COUNT(*)?","options":["SUM = 3, COUNT = 17","SUM = 17, COUNT = 3","Оба 17","Оба 3"],"explanation":"SUM складывает значения (17), COUNT считает записи (3)."},"en":{"title":"COUNT or SUM?","prompt":"Classical has 3 books with 10, 4 and 3 copies. What do SUM(qty) and COUNT(*) give?","options":["SUM = 3, COUNT = 17","SUM = 17, COUNT = 3","Both 17","Both 3"],"explanation":"SUM adds the values (17), COUNT counts the records (3)."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s9$::jsonb),
    ($s9$2.6 Диаграммалар$s9$, $s9$Информатика$s9$, 5, $s9${"summary":"Деректерді көрнекі көрсету: бағанды, сызықтық және дөңгелек диаграмма. Диаграмма қорытынды кестеден салынады: SQL-де GROUP BY, кестеде диаграмма.","objectives":["Бағанды, сызықтық және дөңгелек диаграмманың қолданылуын ажырату","Диаграммаға арналған қорытынды кестені сұраныспен дайындау","Кестеде диаграмма салып, одан қорытынды жасау"],"grade":9,"duration":"45 минут","prior":"GROUP BY және SUM, COUNT функцияларымен қорытынды жасай алады (2.5 сабақ).","env":"ClassFlow кестесі және ClassFlow SQL редакторы (браузерде, орнату керек емес). Әр оқушыға бір құрылғы және интернет қажет. Google аккаунты керек емес.","source":"Информатика, 9-сынып оқулығы, 2-тарау, 34–35 беттер. Сабақ оқулықтан әдейі ауытқиды: Google Forms орнына әр тақырып кестеде және SQL-де қатар орындалады. Барлық сұраныстар мен жауаптар орындалып тексерілген, деректер оқу үшін құрастырылған.","stages":[{"k":"warmup","min":5,"do":"GROUP BY және SUM туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Диаграмма түрлерін және қай кезде қайсысы керегін үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге жанр бойынша қорытындыдан бағанды және дөңгелек диаграмма салады"},{"k":"practice","min":15,"do":"Диаграммаға дерек дайындайтын сұраныс жазады, екі сұраққа жауап береді; үлгерген оқушы ★ сұранысты орындайды"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Наглядное представление данных: столбчатая, линейная и круговая диаграммы. Диаграмму строят по итоговой таблице: GROUP BY в SQL, диаграмма в таблице.","objectives":["Различать назначение столбчатой, линейной и круговой диаграмм","Готовить запросом итоговую таблицу для диаграммы","Строить диаграмму в таблице и делать по ней вывод"],"prior":"Умеют строить итог с GROUP BY и функциями SUM, COUNT (урок 2.5).","env":"Таблица ClassFlow и SQL-редактор ClassFlow (в браузере, устанавливать ничего не нужно). Каждому ученику нужны устройство и интернет. Аккаунт Google не нужен.","source":"Информатика, учебник 9 класса, глава 2, с. 34–35. Урок намеренно отходит от учебника: вместо Google Forms каждая тема выполняется параллельно в таблице и в SQL. Все запросы и ответы проверены выполнением, данные учебные.","stages":["Отвечает на два вопроса о GROUP BY и SUM","Изучает виды диаграмм и когда какая нужна","Вместе с учителем строит столбчатую и круговую диаграммы по итогам жанров","Пишет запрос, готовящий данные для диаграммы, отвечает на два вопроса; кто успел — запрос ★","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"Showing data at a glance: bar, line and pie charts. A chart is drawn from a summary table: GROUP BY in SQL, the chart in a sheet.","objectives":["Tell what bar, line and pie charts are used for","Prepare the summary table for a chart with a query","Draw a chart in a sheet and draw a conclusion from it"],"prior":"Can build a summary with GROUP BY, SUM and COUNT (lesson 2.5).","env":"The ClassFlow sheet and the ClassFlow SQL editor (in the browser, nothing to install). One device per student and the internet. No Google account is needed.","source":"Informatics, Grade 9 textbook, chapter 2, pp. 34–35. The lesson leaves the textbook on purpose: instead of Google Forms every topic is done side by side in a sheet and in SQL. Every query and answer was run; the data are made for the classroom.","stages":["Answers two questions about GROUP BY and SUM","Learns the chart types and when each is needed","Draws a bar and a pie chart from the genre summary with the teacher","Writes a query that prepares data for a chart and answers two questions; fast students take the ★ query","Takes a short test and says what was learned"]}}$s9$::jsonb, $s9$[{"term":"chart","definition":"Диаграмма — деректерді көрнекі көрсететін сурет · Диаграмма — наглядное изображение данных · Chart — a picture that shows data at a glance"},{"term":"bar chart","definition":"Бағанды диаграмма — топтарды өзара салыстырады · Столбчатая диаграмма — сравнивает группы между собой · Bar chart — compares groups with each other"},{"term":"line chart","definition":"Сызықтық диаграмма — уақыт бойынша өзгерісті көрсетеді · Линейная диаграмма — показывает изменение во времени · Line chart — shows change over time"},{"term":"pie chart","definition":"Дөңгелек диаграмма — бүтіннің бөліктерін көрсетеді · Круговая диаграмма — показывает части целого · Pie chart — shows the parts of a whole"}]$s9$::jsonb, $s9$[{"type":"title","pageType":"slide","templateId":"title","title":"2.6 Диаграммалар","subtitle":"Информатика 9-сынып · 2-тарау «Деректер қоры» · оқулық 34–35-б.","ru":{"title":"2.6 Диаграммы","subtitle":"Информатика 9 класс · глава 2 «Базы данных» · учебник, с. 34–35"},"en":{"title":"2.6 Charts","subtitle":"Informatics Grade 9 · Chapter 2 “Databases” · textbook pp. 34–35"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: GROUP BY","prompt":"SELECT genre, SUM(qty) FROM books GROUP BY genre; нәтижесінде неше жол шығады (кітапханада 4 жанр бар)?","options":["8","4","1","52"],"answer":1,"explanation":"Әр топқа бір жол: 4 жанр — 4 жол.","points":1,"ru":{"title":"Повторение: GROUP BY","prompt":"Сколько строк даст SELECT genre, SUM(qty) FROM books GROUP BY genre; (в библиотеке 4 жанра)?","options":["8","4","1","52"],"explanation":"На каждую группу одна строка: 4 жанра — 4 строки.","notes":"5 минут. Вопрос: «Таблица чисел или картинка: по чему быстрее сделать вывод?»"},"en":{"title":"Review: GROUP BY","prompt":"How many rows does SELECT genre, SUM(qty) FROM books GROUP BY genre; return (the library has 4 genres)?","options":["8","4","1","52"],"explanation":"One row per group: 4 genres make 4 rows.","notes":"5 minutes. Ask: “A table of numbers or a picture: which gives a conclusion faster?”"},"stage":"warmup","notes":"5 минут. Сұрақ: «Сандар кестесі мен сурет: қайсысынан қорытынды тез шығады?»"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: SUMIF","prompt":"=SUMIF(B2:B9;\"History\";D2:D9) нені есептейді?","options":["History жанрындағы кітап атауларының санын","Барлық кітаптың жалпы санын","History жанрындағы ең ескі жылды","History жанрындағы кітаптардың жалпы дана санын"],"answer":3,"explanation":"SUMIF B бағанынан жанрды тауып, D бағанындағы сандарды қосады.","points":1,"ru":{"title":"Повторение: SUMIF","prompt":"Что считает =SUMIF(B2:B9;\"History\";D2:D9)?","options":["Число названий жанра History","Общее количество всех книг","Самый старый год жанра History","Общее количество экземпляров жанра History"],"explanation":"SUMIF находит жанр в столбце B и складывает количество из столбца D."},"en":{"title":"Review: SUMIF","prompt":"What does =SUMIF(B2:B9;\"History\";D2:D9) work out?","options":["The number of History titles","The total of all books","The oldest year in History","The total copies of the History books"],"explanation":"SUMIF finds the genre in column B and adds the quantities from column D."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Диаграмма түрлері","bullets":["Бағанды диаграмма (bar) топтарды салыстырады: қай жанрда кітап көп?","Сызықтық диаграмма (line) уақыт бойынша өзгерісті көрсетеді: кітап саны жыл сайын қалай өзгерді?","Дөңгелек диаграмма (pie) бүтіннің бөліктерін көрсетеді: әр жанр кітапхананың қандай үлесін алады?"],"ru":{"title":"Виды диаграмм","bullets":["Столбчатая диаграмма (bar) сравнивает группы: в каком жанре больше книг?","Линейная диаграмма (line) показывает изменение во времени: как менялось число книг по годам?","Круговая диаграмма (pie) показывает части целого: какую долю библиотеки занимает каждый жанр?"],"notes":"8 минут (два слайда). Попросите пример из жизни на каждый вид: погода (линейная), оценки класса (столбчатая), семейный бюджет (круговая)."},"en":{"title":"Chart types","bullets":["A bar chart compares groups: which genre has more books?","A line chart shows change over time: how did the number of books change year by year?","A pie chart shows the parts of a whole: what share of the library is each genre?"],"notes":"8 minutes (two slides). Ask for a real-life example of each type: weather (line), class marks (bar), a family budget (pie)."},"stage":"together","notes":"8 минут (екі слайд). Әр түрге өмірден мысал сұраңыз: ауа райы (сызықтық), сынып бағалары (бағанды), отбасы бюджеті (дөңгелек).","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Деректер қорынан диаграммаға","bullets":["1-қадам: сұраныс қорытынды кесте береді — әр топқа бір жол (GROUP BY).","2-қадам: қорытынды кестені белгілеп, кестедегі диаграмма батырмасын бас: бағанды, сызықтық немесе дөңгелек.","Ең үлкен мәндерді ғана көрсету үшін: ORDER BY … DESC LIMIT 3 — алғашқы үш жолды қалдырады."],"code":"SELECT genre, SUM(qty) AS total FROM books GROUP BY genre;\nSELECT title, qty FROM books ORDER BY qty DESC LIMIT 3;","lang":"text","ru":{"title":"От базы данных к диаграмме","bullets":["Шаг 1: запрос даёт итоговую таблицу — по строке на группу (GROUP BY).","Шаг 2: выдели итоговую таблицу и нажми кнопку диаграммы в таблице: столбчатая, линейная или круговая.","Чтобы показать только наибольшие значения: ORDER BY … DESC LIMIT 3 — оставляет первые три строки."]},"en":{"title":"From a database to a chart","bullets":["Step 1: a query gives a summary table, one row per group (GROUP BY).","Step 2: select the summary table and press the chart button of the sheet: bar, line or pie.","To show only the largest values: ORDER BY … DESC LIMIT 3 keeps the first three rows."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: жанрлар диаграммасы","bullets":["A1:B5 — жанр бойынша қорытынды кесте. Астында екі диаграмма тұр: бағанды және дөңгелек.","Бағанды диаграммадан: қай жанрда кітап ең көп, қайсысында ең аз?","B4 ұяшығындағы санды 30-ға өзгерт: екі диаграмма қалай өзгерді?"],"demoSheet":{"rows":7,"cols":3,"cells":{"A1":"Жанр","B1":"Жалпы саны","A2":"Classical","B2":"17","A3":"History","B3":"6","A4":"Adventure","B4":"24","A5":"Detective","B5":"5"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"}},"charts":[{"id":"bar","type":"bar","range":"A1:B5"},{"id":"pie","type":"pie","range":"A1:B5"}]},"notes":"10 минут (осы және келесі слайд). Ең көбі — Adventure (24), ең азы — Detective (5). Дөңгелек диаграммада Adventure шамамен жартысына жуық (24 / 52). Диаграмма деректерге байланған: сан өзгерсе, сурет те өзгереді.","ru":{"title":"Пример: диаграмма жанров","bullets":["A1:B5 — итоговая таблица по жанрам. Под ней две диаграммы: столбчатая и круговая.","По столбчатой диаграмме: в каком жанре книг больше всего, в каком меньше?","Измени число в B4 на 30: как изменились обе диаграммы?"],"demoSheet":{"rows":7,"cols":3,"cells":{"A1":"Жанр","B1":"Всего штук","A2":"Classical","B2":"17","A3":"History","B3":"6","A4":"Adventure","B4":"24","A5":"Detective","B5":"5"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"}},"charts":[{"id":"bar","type":"bar","range":"A1:B5"},{"id":"pie","type":"pie","range":"A1:B5"}]},"notes":"10 минут (этот и следующий слайд). Больше всего — Adventure (24), меньше всего — Detective (5). На круговой диаграмме Adventure занимает почти половину (24 / 52). Диаграмма связана с данными: меняется число — меняется рисунок."},"en":{"title":"Example: the genre chart","bullets":["A1:B5 is the summary by genre. Two charts stand below it: a bar chart and a pie chart.","From the bar chart: which genre has the most books and which the fewest?","Change the number in B4 to 30: how did both charts change?"],"demoSheet":{"rows":7,"cols":3,"cells":{"A1":"Genre","B1":"Total copies","A2":"Classical","B2":"17","A3":"History","B3":"6","A4":"Adventure","B4":"24","A5":"Detective","B5":"5"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"}},"charts":[{"id":"bar","type":"bar","range":"A1:B5"},{"id":"pie","type":"pie","range":"A1:B5"}]},"notes":"10 minutes (this and the next slide). The most is Adventure (24), the fewest Detective (5). On the pie chart Adventure takes almost half (24 / 52). The chart is tied to the data: change a number and the picture changes."},"stage":"example"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: диаграммаға дерек дайындау","bullets":["«Орындау» бас: бұл — алдыңғы слайдтағы қорытынды кесте, бірақ оны сұраныс жасады.","AS total — бағанға ат береді. ORDER BY total DESC — ең көп жанр бірінші тұрады.","Соңына LIMIT 2 қос: тек ең көп екі жанр қалады."],"code":"SELECT genre, SUM(qty) AS total FROM books GROUP BY genre ORDER BY total DESC;","lang":"sql","sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"SELECT genre, SUM(qty) AS total FROM books GROUP BY genre ORDER BY total DESC;"},"notes":"Нәтиже: Adventure 24, Classical 17, History 6, Detective 5. LIMIT 2: Adventure мен Classical. LIMIT әрқашан сұраныстың ең соңында тұрады.","ru":{"title":"Пример: готовим данные для диаграммы","bullets":["Нажми «Выполнить»: это итоговая таблица с прошлого слайда, но её построил запрос.","AS total — даёт столбцу имя. ORDER BY total DESC — жанр с наибольшим количеством идёт первым.","Добавь в конец LIMIT 2: останутся только два самых больших жанра."],"notes":"Результат: Adventure 24, Classical 17, History 6, Detective 5. LIMIT 2: Adventure и Classical. LIMIT всегда стоит в самом конце запроса."},"en":{"title":"Example: preparing data for a chart","bullets":["Press “Run”: this is the summary table of the previous slide, but a query built it.","AS total names the column. ORDER BY total DESC puts the genre with the most copies first.","Add LIMIT 2 at the end: only the two largest genres remain."],"notes":"Result: Adventure 24, Classical 17, History 6, Detective 5. LIMIT 2: Adventure and Classical. LIMIT always comes last in a query."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["d3e96a53"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","ordered":true,"rows":3},"title":"Практика 1: ең көп үш кітап","prompt":"Диаграммаға дерек дайында: дана саны ең көп үш кітаптың атауы (title) мен санын (qty) саны көбінен азына қарай көрсет.","notes":"15 минут (төрт тапсырма). Дұрыс сұраныс: SELECT title, qty FROM books ORDER BY qty DESC LIMIT 3; Жолдардың реті де тексеріледі.","ru":{"title":"Практика 1: три самые многочисленные книги","prompt":"Подготовь данные для диаграммы: покажи название (title) и количество (qty) трёх книг с наибольшим количеством, от большего к меньшему.","notes":"15 минут (четыре задания). Верный запрос: SELECT title, qty FROM books ORDER BY qty DESC LIMIT 3; Проверяется и порядок строк."},"en":{"title":"Practice 1: the top three books","prompt":"Prepare data for a chart: show the title and the quantity of the three books with the most copies, largest first.","notes":"15 minutes (four tasks). Correct query: SELECT title, qty FROM books ORDER BY qty DESC LIMIT 3; The row order is checked too."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 2: диаграмманы оқы","prompt":"Жанрлар диаграммасында ең биік баған қай жанрға тиесілі? Жанр атын ағылшынша жаз.","accept":["adventure"],"points":1,"notes":"Adventure — 24 дана, ең көбі.","ru":{"title":"Практика 2: прочитай диаграмму","prompt":"Какому жанру принадлежит самый высокий столбец на диаграмме жанров? Напиши название жанра по-английски.","notes":"Adventure — 24 штуки, больше всех."},"en":{"title":"Practice 2: read the chart","prompt":"Which genre has the tallest bar on the genre chart? Type the genre name in English.","notes":"Adventure has 24 copies, the most."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 3: диаграмма түрі","prompt":"Әр жанр кітапхананың қандай үлесін алатынын көрсету керек. Қай диаграмма түрі ең қолайлы? Ағылшынша бір сөзбен жаз (bar, line немесе pie).","accept":["pie"],"points":1,"notes":"Бүтіннің бөліктері — дөңгелек диаграмма (pie).","ru":{"title":"Практика 3: вид диаграммы","prompt":"Нужно показать, какую долю библиотеки занимает каждый жанр. Какой вид диаграммы подходит лучше всего? Одно слово по-английски (bar, line или pie).","notes":"Части целого — круговая диаграмма (pie)."},"en":{"title":"Practice 3: the chart type","prompt":"We must show what share of the library each genre takes. Which chart type fits best? One word in English (bar, line or pie).","notes":"Parts of a whole call for a pie chart."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":3,"accept":["e6dc30bc"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","ordered":true,"rows":4},"title":"★ Күрделі: жанр бойынша толық есеп","prompt":"Әр жанр үшін үш баған шығар: жанр, кітап атауларының саны (COUNT(*)) және жалпы дана саны (SUM(qty)). Нәтижені жалпы дана саны бойынша кему ретімен көрсет.","notes":"Жылдам оқушыларға. Бір сұраныста екі функция. Осы кестеден екі диаграмма салуға болады: кітап атауларының саны және дана саны.","ru":{"title":"★ Сложнее: полный отчёт по жанрам","prompt":"Для каждого жанра выведи три столбца: жанр, число названий (COUNT(*)) и общее количество (SUM(qty)). Результат — по убыванию общего количества.","notes":"Для быстрых учеников. Две функции в одном запросе. По этой таблице можно построить две диаграммы: число названий и количество экземпляров."},"en":{"title":"★ Harder: a full report by genre","prompt":"For each genre return three columns: the genre, the number of titles (COUNT(*)) and the total copies (SUM(qty)). Order by the total copies, descending.","notes":"For fast students. Two functions in one query. Two charts can be drawn from this table: titles and copies."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Уақыт бойынша өзгеріс","prompt":"Кітапханадағы кітап саны 2020 жылдан 2026 жылға дейін қалай өзгергенін көрсету керек. Қай диаграмма қолайлы?","options":["Сызықтық (line)","Дөңгелек (pie)","Ешқайсысы","Тек кесте"],"answer":0,"explanation":"Уақыт бойынша өзгеріс — сызықтық диаграмма.","points":1,"ru":{"title":"Изменение во времени","prompt":"Нужно показать, как менялось число книг в библиотеке с 2020 по 2026 год. Какая диаграмма подходит?","options":["Линейная (line)","Круговая (pie)","Никакая","Только таблица"],"explanation":"Изменение во времени — линейная диаграмма.","notes":"7 минут: два вопроса и итог."},"en":{"title":"Change over time","prompt":"We must show how the number of books changed from 2020 to 2026. Which chart fits?","options":["Line","Pie","None","Only a table"],"explanation":"Change over time calls for a line chart.","notes":"7 minutes: two questions and the wrap-up."},"stage":"check","notes":"7 минут: екі сұрақ және қорытынды."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"LIMIT","prompt":"Сұраныстың соңындағы LIMIT 3 не істейді?","options":["3-жазбаны өшіреді","Үш өрісті ғана көрсетеді","Нәтиженің алғашқы үш жолын ғана қалдырады","Сұранысты үш рет орындайды"],"answer":2,"explanation":"LIMIT n нәтиженің алғашқы n жолын қалдырады.","points":1,"ru":{"title":"LIMIT","prompt":"Что делает LIMIT 3 в конце запроса?","options":["Удаляет третью запись","Показывает только три поля","Оставляет только первые три строки результата","Выполняет запрос три раза"],"explanation":"LIMIT n оставляет первые n строк результата."},"en":{"title":"LIMIT","prompt":"What does LIMIT 3 at the end of a query do?","options":["Deletes the third record","Shows only three fields","Keeps only the first three rows of the result","Runs the query three times"],"explanation":"LIMIT n keeps the first n rows of the result."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s9$::jsonb),
    ($s9$2.7 Шағын жоба: отбасылық дүкен$s9$, $s9$Информатика$s9$, 6, $s9${"summary":"Дүкендегі тауарларды есепке алатын деректер қоры: жобалау, толтыру, сұрыптау, топтау, диаграмма. Есептелетін өріс: саны × бағасы. Деректер қорының түрлері.","objectives":["Тарауда үйренгендерді бір жобада қолдану","Есептелетін өріс жазу: саны × бағасы","Деректер қорының түрлерін атау"],"grade":9,"duration":"45 минут","prior":"SELECT, WHERE, ORDER BY, GROUP BY жаза алады; кестеде SUMIF қолданады, диаграмма түрлерін біледі (2.1–2.6 сабақтар).","env":"ClassFlow кестесі және ClassFlow SQL редакторы (браузерде, орнату керек емес). Әр оқушыға бір құрылғы және интернет қажет. Google аккаунты керек емес.","source":"Информатика, 9-сынып оқулығы, 2-тарау, 36–37 беттер. Сабақ оқулықтан әдейі ауытқиды: Google Forms орнына әр тақырып кестеде және SQL-де қатар орындалады. Барлық сұраныстар мен жауаптар орындалып тексерілген, деректер оқу үшін құрастырылған.","stages":[{"k":"warmup","min":5,"do":"Диаграмма және COUNT туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Жоба қадамдарын және деректер қорының түрлерін үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге әр тауардың құнын есептейтін сұраныс орындайды"},{"k":"practice","min":15,"do":"Дүкен кестесін есептейді, SQL-де екі есеп жазады; үлгерген оқушы ★ сұранысты орындайды"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"База данных для учёта товаров магазина: проект, заполнение, сортировка, группировка, диаграмма. Вычисляемое поле: количество × цена. Виды баз данных.","objectives":["Применять изученное в главе в одном проекте","Записывать вычисляемое поле: количество × цена","Называть виды баз данных"],"prior":"Умеют писать SELECT, WHERE, ORDER BY, GROUP BY; применяют SUMIF в таблице и знают виды диаграмм (уроки 2.1–2.6).","env":"Таблица ClassFlow и SQL-редактор ClassFlow (в браузере, устанавливать ничего не нужно). Каждому ученику нужны устройство и интернет. Аккаунт Google не нужен.","source":"Информатика, учебник 9 класса, глава 2, с. 36–37. Урок намеренно отходит от учебника: вместо Google Forms каждая тема выполняется параллельно в таблице и в SQL. Все запросы и ответы проверены выполнением, данные учебные.","stages":["Отвечает на два вопроса о диаграммах и COUNT","Изучает шаги проекта и виды баз данных","Вместе с учителем выполняет запрос, считающий стоимость каждого товара","Считает таблицу магазина и пишет два отчёта в SQL; кто успел — запрос ★","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"A database for counting the goods of a shop: design, filling, sorting, grouping, a chart. A calculated field: quantity × price. Types of databases.","objectives":["Use everything learned in the chapter in one project","Write a calculated field: quantity × price","Name the types of databases"],"prior":"Can write SELECT, WHERE, ORDER BY and GROUP BY; use SUMIF in a sheet and know the chart types (lessons 2.1–2.6).","env":"The ClassFlow sheet and the ClassFlow SQL editor (in the browser, nothing to install). One device per student and the internet. No Google account is needed.","source":"Informatics, Grade 9 textbook, chapter 2, pp. 36–37. The lesson leaves the textbook on purpose: instead of Google Forms every topic is done side by side in a sheet and in SQL. Every query and answer was run; the data are made for the classroom.","stages":["Answers two questions about charts and COUNT","Learns the project steps and the types of databases","Runs a query that works out the value of each item with the teacher","Works out the shop sheet and writes two SQL reports; fast students take the ★ query","Takes a short test and says what was learned"]}}$s9$::jsonb, $s9$[{"term":"calculated field","definition":"Есептелетін өріс — басқа өрістерден формуламен шығатын мән · Вычисляемое поле — значение, полученное формулой из других полей · Calculated field — a value worked out from other fields"},{"term":"centralized database","definition":"Орталықтандырылған деректер қоры — бір орталық компьютерде сақталады, оған әр жерден қосылады · Централизованная база данных — хранится на одном центральном компьютере, к ней подключаются из разных мест · Centralized database — kept on one central computer and reached from many places"},{"term":"personal database","definition":"Жеке деректер қоры — бір компьютерде, шағын топ қолданады · Персональная база данных — на одном компьютере, для небольшой группы · Personal database — on one computer, used by a small group"}]$s9$::jsonb, $s9$[{"type":"title","pageType":"slide","templateId":"title","title":"2.7 Шағын жоба: отбасылық дүкен","subtitle":"Информатика 9-сынып · 2-тарау «Деректер қоры» · оқулық 36–37-б.","ru":{"title":"2.7 Мини-проект: семейный магазин","subtitle":"Информатика 9 класс · глава 2 «Базы данных» · учебник, с. 36–37"},"en":{"title":"2.7 Mini project: family shop","subtitle":"Informatics Grade 9 · Chapter 2 “Databases” · textbook pp. 36–37"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: диаграмма","prompt":"Бірнеше топты өзара салыстыруға қай диаграмма ең қолайлы?","options":["Дөңгелек","Сызықтық","Бағанды","Ешқайсысы"],"answer":2,"explanation":"Топтарды салыстыру — бағанды диаграмма.","points":1,"ru":{"title":"Повторение: диаграмма","prompt":"Какая диаграмма лучше всего сравнивает несколько групп?","options":["Круговая","Линейная","Столбчатая","Никакая"],"explanation":"Сравнение групп — столбчатая диаграмма.","notes":"5 минут. Вопрос: «Если бы у вашей семьи был магазин, как бы вы вели учёт товаров?»"},"en":{"title":"Review: charts","prompt":"Which chart is best for comparing several groups?","options":["Pie","Line","Bar","None"],"explanation":"Comparing groups calls for a bar chart.","notes":"5 minutes. Ask: “If your family had a shop, how would you keep track of the goods?”"},"stage":"warmup","notes":"5 минут. Сұрақ: «Отбасыңыздың дүкені болса, тауарларды қалай есепке алар едіңіз?»"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: COUNT","prompt":"SELECT COUNT(*) FROM books; нені береді (кестеде 8 кітап, барлығы 52 дана)?","options":["8","52","7","4"],"answer":0,"explanation":"COUNT(*) жазбаларды санайды: 8. 52 — SUM(qty).","points":1,"ru":{"title":"Повторение: COUNT","prompt":"Что даст SELECT COUNT(*) FROM books; (в таблице 8 книг, всего 52 экземпляра)?","options":["8","52","7","4"],"explanation":"COUNT(*) считает записи: 8. 52 — это SUM(qty)."},"en":{"title":"Review: COUNT","prompt":"What does SELECT COUNT(*) FROM books; give (8 books, 52 copies in all)?","options":["8","52","7","4"],"explanation":"COUNT(*) counts the records: 8. 52 is SUM(qty)."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Жоба қадамдары","bullets":["Жобалау: goods кестесі — id, name (TEXT), category (TEXT), qty (INTEGER), price (INTEGER).","Толтыру және сұрау: тауарларды қосамыз (INSERT), бағасы бойынша сұрыптаймыз (ORDER BY), санаты бойынша сүзеді (WHERE).","Қорытынды: санат бойынша топтаймыз (GROUP BY) және диаграмма саламыз. Тауардың құны = саны × бағасы."],"code":"SELECT name, qty * price AS value FROM goods;","lang":"text","ru":{"title":"Шаги проекта","bullets":["Проект: таблица goods — id, name (TEXT), category (TEXT), qty (INTEGER), price (INTEGER).","Заполнение и запросы: добавляем товары (INSERT), сортируем по цене (ORDER BY), отбираем по категории (WHERE).","Итог: группируем по категории (GROUP BY) и строим диаграмму. Стоимость товара = количество × цена."],"notes":"8 минут (два слайда). Свяжите шаги с уроками главы: 2.2 — проект, 2.3 — заполнение, 2.4 — фильтр и сортировка, 2.5 — группировка, 2.6 — диаграмма."},"en":{"title":"The project steps","bullets":["Design: the table goods has id, name (TEXT), category (TEXT), qty (INTEGER), price (INTEGER).","Filling and querying: add the goods (INSERT), sort by price (ORDER BY), filter by category (WHERE).","Summary: group by category (GROUP BY) and draw a chart. The value of an item = quantity × price."],"notes":"8 minutes (two slides). Tie the steps to the lessons of the chapter: 2.2 design, 2.3 filling, 2.4 filter and sort, 2.5 grouping, 2.6 chart."},"stage":"together","notes":"8 минут (екі слайд). Қадамдарды тараудың сабақтарымен байланыстырыңыз: 2.2 — жобалау, 2.3 — толтыру, 2.4 — сүзу мен сұрыптау, 2.5 — топтау, 2.6 — диаграмма.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Деректер қорының түрлері","bullets":["Орталықтандырылған (centralized): барлық дерек бір орталықта, пайдаланушылар оған әр жерден қосылады. Мысалы, банк қоры.","Жеке (personal): бір компьютерде сақталады, шағын топ қолданады. Мысалы, біздің дүкеннің қоры.","Үлестірілген (distributed): деректер бірнеше жердегі компьютерлерде сақталып, бір қор ретінде жұмыс істейді."],"ru":{"title":"Виды баз данных","bullets":["Централизованная (centralized): все данные в одном центре, пользователи подключаются из разных мест. Например, база банка.","Персональная (personal): хранится на одном компьютере, ею пользуется небольшая группа. Например, база нашего магазина.","Распределённая (distributed): данные хранятся на компьютерах в разных местах и работают как одна база."]},"en":{"title":"Types of databases","bullets":["Centralized: all the data are in one centre and users connect from many places. For example, a bank’s database.","Personal: kept on one computer and used by a small group. For example, the database of our shop.","Distributed: the data are kept on computers in several places and work as one database."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: әр тауардың құны","bullets":["«Орындау» бас: qty * price — есептелетін өріс, ол кестеде сақталмайды, сұраныс кезінде есептеледі.","Ең қымбат тауар тобы қайсы? Нәтиже құны бойынша кему ретімен тұр.","Сұранысты SELECT SUM(qty * price) FROM goods; деп өзгерт: дүкендегі барлық тауардың құны шығады."],"code":"SELECT name, qty * price AS value FROM goods ORDER BY value DESC;","lang":"sql","sql":{"setup":"CREATE TABLE goods (id INTEGER PRIMARY KEY, name TEXT, category TEXT, qty INTEGER, price INTEGER);\nINSERT INTO goods VALUES\n  (1, 'Нан', 'Food', 20, 150),\n  (2, 'Сүт', 'Drinks', 15, 420),\n  (3, 'Шай', 'Drinks', 10, 900),\n  (4, 'Сабын', 'Household', 12, 300),\n  (5, 'Күріш', 'Food', 8, 650),\n  (6, 'Шырын', 'Drinks', 9, 550);","start":"SELECT name, qty * price AS value FROM goods ORDER BY value DESC;"},"notes":"10 минут. Нәтиже: Шай 9000, Сүт 6300, Күріш 5200, Шырын 4950, Сабын 3600, Нан 3000. Барлығы 32050. Бағалар оқу үшін ойдан алынған.","ru":{"title":"Пример: стоимость каждого товара","bullets":["Нажми «Выполнить»: qty * price — вычисляемое поле, оно не хранится в таблице, а считается при запросе.","Какая позиция самая дорогая? Результат идёт по убыванию стоимости.","Измени запрос на SELECT SUM(qty * price) FROM goods;: выйдет стоимость всех товаров магазина."],"notes":"10 минут. Результат: Шай 9000, Сүт 6300, Күріш 5200, Шырын 4950, Сабын 3600, Нан 3000. Всего 32050. Цены учебные, придуманные."},"en":{"title":"Example: the value of each item","bullets":["Press “Run”: qty * price is a calculated field; it is not stored in the table but worked out by the query.","Which item is worth the most? The result is ordered by value, descending.","Change the query to SELECT SUM(qty * price) FROM goods;: the value of all the goods in the shop."],"notes":"10 minutes. Result: Шай 9000, Сүт 6300, Күріш 5200, Шырын 4950, Сабын 3600, Нан 3000. 32050 in all. The prices are made up for the lesson."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 1: дүкен кестесі","prompt":"Дүкен кестесі дайын. Әр тауардың құнын (саны × бағасы), барлық тауардың құнын және Drinks санатының құнын формуламен есепте.","points":6,"picture":"lec/inf8-g9-shop-kk.svg","pictureAlt":"Алты тауардың атауы, санаты, саны және бағасы; құны, жалпы құн және Drinks құны бос","sheet":{"rows":11,"cols":6,"cells":{"A1":"Тауар","B1":"Санаты","C1":"Саны","D1":"Бағасы","E1":"Құны","A2":"Нан","B2":"Food","C2":"20","D2":"150","A3":"Сүт","B3":"Drinks","C3":"15","D3":"420","A4":"Шай","B4":"Drinks","C4":"10","D4":"900","A5":"Сабын","B5":"Household","C5":"12","D5":"300","A6":"Күріш","B6":"Food","C6":"8","D6":"650","A7":"Шырын","B7":"Drinks","C7":"9","D7":"550","A8":"Барлығы","A9":"Drinks құны"}},"criteria":[{"id":"c1","text":"E2 — нанның құны (формуламен)","cell":"E2","points":1,"formula":true,"accept":["3000"]},{"id":"c2","text":"E7 — шырынның құны (формуламен)","cell":"E7","points":1,"formula":true,"accept":["4950"]},{"id":"c3","text":"E8 — барлық тауардың құны (SUM)","cell":"E8","points":2,"fn":"SUM","accept":["32050"]},{"id":"c4","text":"★ E9 — Drinks санатының құны (SUMIF)","cell":"E9","points":2,"fn":"SUMIF","accept":["20250"]}],"steps":["Көмек: E2 ұяшығына =C2*D2 жаз да, E7-ге дейін төмен көшір.","E8-ге =SUM(E2:E7) жаз.","★ E9: Drinks санатындағы тауарлардың құнын SUMIF көмегімен қос."],"notes":"15 минут (төрт тапсырма). Күтілетін нәтиже: E2 = 3000, E3 = 6300, E4 = 9000, E5 = 3600, E6 = 5200, E7 = 4950; E8 = 32050; E9 = 20250.","ru":{"title":"Практика 1: таблица магазина","prompt":"Таблица магазина готова. Формулами посчитай стоимость каждого товара (количество × цена), стоимость всех товаров и стоимость категории Drinks.","picture":"lec/inf8-g9-shop-ru.svg","pictureAlt":"Название, категория, количество и цена шести товаров; стоимость, общая стоимость и стоимость Drinks пустые","criteria":[{"id":"c1","text":"E2 — стоимость хлеба (формулой)","cell":"E2","points":1,"formula":true},{"id":"c2","text":"E7 — стоимость сока (формулой)","cell":"E7","points":1,"formula":true},{"id":"c3","text":"E8 — стоимость всех товаров (SUM)","cell":"E8","points":2,"fn":"SUM"},{"id":"c4","text":"★ E9 — стоимость категории Drinks (SUMIF)","cell":"E9","points":2,"fn":"SUMIF"}],"steps":["Подсказка: в E2 запиши =C2*D2 и протяни вниз до E7.","В E8 запиши =SUM(E2:E7).","★ E9: сложи стоимость товаров категории Drinks функцией SUMIF."],"notes":"15 минут (четыре задания). Ожидаемый результат: E2 = 3000, E3 = 6300, E4 = 9000, E5 = 3600, E6 = 5200, E7 = 4950; E8 = 32050; E9 = 20250.","sheet":{"rows":11,"cols":6,"cells":{"A1":"Товар","B1":"Категория","C1":"Кол-во","D1":"Цена","E1":"Стоимость","A2":"Нан","B2":"Food","C2":"20","D2":"150","A3":"Сүт","B3":"Drinks","C3":"15","D3":"420","A4":"Шай","B4":"Drinks","C4":"10","D4":"900","A5":"Сабын","B5":"Household","C5":"12","D5":"300","A6":"Күріш","B6":"Food","C6":"8","D6":"650","A7":"Шырын","B7":"Drinks","C7":"9","D7":"550","A8":"Всего","A9":"Стоимость Drinks"}}},"en":{"title":"Practice 1: the shop sheet","prompt":"The shop sheet is ready. With formulas work out the value of each item (quantity × price), the value of all goods and the value of the Drinks category.","picture":"lec/inf8-g9-shop-en.svg","pictureAlt":"Name, category, quantity and price of six goods; the value, the total and the Drinks value are empty","criteria":[{"id":"c1","text":"E2 — the value of the bread (formula)","cell":"E2","points":1,"formula":true},{"id":"c2","text":"E7 — the value of the juice (formula)","cell":"E7","points":1,"formula":true},{"id":"c3","text":"E8 — the value of all goods (SUM)","cell":"E8","points":2,"fn":"SUM"},{"id":"c4","text":"★ E9 — the value of the Drinks category (SUMIF)","cell":"E9","points":2,"fn":"SUMIF"}],"steps":["Hint: in E2 type =C2*D2 and fill down to E7.","In E8 type =SUM(E2:E7).","★ E9: add the value of the Drinks goods with SUMIF."],"notes":"15 minutes (four tasks). Expected: E2 = 3000, E3 = 6300, E4 = 9000, E5 = 3600, E6 = 5200, E7 = 4950; E8 = 32050; E9 = 20250.","sheet":{"rows":11,"cols":6,"cells":{"A1":"Item","B1":"Category","C1":"Qty","D1":"Price","E1":"Value","A2":"Нан","B2":"Food","C2":"20","D2":"150","A3":"Сүт","B3":"Drinks","C3":"15","D3":"420","A4":"Шай","B4":"Drinks","C4":"10","D4":"900","A5":"Сабын","B5":"Household","C5":"12","D5":"300","A6":"Күріш","B6":"Food","C6":"8","D6":"650","A7":"Шырын","B7":"Drinks","C7":"9","D7":"550","A8":"Total","A9":"Drinks value"}}},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["949eb205"],"sql":{"setup":"CREATE TABLE goods (id INTEGER PRIMARY KEY, name TEXT, category TEXT, qty INTEGER, price INTEGER);\nINSERT INTO goods VALUES\n  (1, 'Нан', 'Food', 20, 150),\n  (2, 'Сүт', 'Drinks', 15, 420),\n  (3, 'Шай', 'Drinks', 10, 900),\n  (4, 'Сабын', 'Household', 12, 300),\n  (5, 'Күріш', 'Food', 8, 650),\n  (6, 'Шырын', 'Drinks', 9, 550);","start":"","rows":3},"title":"Практика 2: санат бойынша сан","prompt":"Әр санат (category) үшін тауарлардың жалпы санын (qty қосындысы) көрсет: екі баған — санат және қосынды.","notes":"Дұрыс сұраныс: SELECT category, SUM(qty) FROM goods GROUP BY category;","ru":{"title":"Практика 2: количество по категориям","prompt":"Для каждой категории (category) покажи общее количество товаров (сумму qty): два столбца — категория и сумма.","notes":"Верный запрос: SELECT category, SUM(qty) FROM goods GROUP BY category;"},"en":{"title":"Practice 2: quantity by category","prompt":"For each category show the total quantity of goods (the sum of qty): two columns, the category and the total.","notes":"Correct query: SELECT category, SUM(qty) FROM goods GROUP BY category;"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["1a8f8e46"],"sql":{"setup":"CREATE TABLE goods (id INTEGER PRIMARY KEY, name TEXT, category TEXT, qty INTEGER, price INTEGER);\nINSERT INTO goods VALUES\n  (1, 'Нан', 'Food', 20, 150),\n  (2, 'Сүт', 'Drinks', 15, 420),\n  (3, 'Шай', 'Drinks', 10, 900),\n  (4, 'Сабын', 'Household', 12, 300),\n  (5, 'Күріш', 'Food', 8, 650),\n  (6, 'Шырын', 'Drinks', 9, 550);","start":"","ordered":true,"rows":3},"title":"Практика 3: қымбат тауарлар","prompt":"Бағасы (price) 500-ден қымбат тауарлардың атауы (name) мен бағасын қымбатынан арзанына қарай көрсет.","notes":"Дұрыс сұраныс: SELECT name, price FROM goods WHERE price > 500 ORDER BY price DESC; Жолдардың реті де тексеріледі.","ru":{"title":"Практика 3: дорогие товары","prompt":"Покажи название (name) и цену товаров дороже 500 (price), от самого дорогого к самому дешёвому.","notes":"Верный запрос: SELECT name, price FROM goods WHERE price > 500 ORDER BY price DESC; Проверяется и порядок строк."},"en":{"title":"Practice 3: the expensive goods","prompt":"Show the name and the price of the goods that cost more than 500, most expensive first.","notes":"Correct query: SELECT name, price FROM goods WHERE price > 500 ORDER BY price DESC; The row order is checked too."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":3,"accept":["0f33d321"],"sql":{"setup":"CREATE TABLE goods (id INTEGER PRIMARY KEY, name TEXT, category TEXT, qty INTEGER, price INTEGER);\nINSERT INTO goods VALUES\n  (1, 'Нан', 'Food', 20, 150),\n  (2, 'Сүт', 'Drinks', 15, 420),\n  (3, 'Шай', 'Drinks', 10, 900),\n  (4, 'Сабын', 'Household', 12, 300),\n  (5, 'Күріш', 'Food', 8, 650),\n  (6, 'Шырын', 'Drinks', 9, 550);","start":"","ordered":true,"rows":3},"title":"★ Күрделі: санат бойынша құн","prompt":"Әр санаттағы тауарлардың жалпы құнын (qty * price қосындысы) көрсет. Нәтижені құны бойынша кему ретімен шығар. Екі баған: санат және құны.","notes":"Жылдам оқушыларға. Есептелетін өріс функцияның ішінде: SUM(qty * price). Drinks құны кестедегі E9 ұяшығымен бірдей (20250).","ru":{"title":"★ Сложнее: стоимость по категориям","prompt":"Покажи общую стоимость товаров каждой категории (сумму qty * price). Результат — по убыванию стоимости. Два столбца: категория и стоимость.","notes":"Для быстрых учеников. Вычисляемое поле внутри функции: SUM(qty * price). Стоимость Drinks совпадает с ячейкой E9 в таблице (20250)."},"en":{"title":"★ Harder: value by category","prompt":"Show the total value of the goods in each category (the sum of qty * price). Order by the value, descending. Two columns: the category and the value.","notes":"For fast students. A calculated field inside a function: SUM(qty * price). The Drinks value equals cell E9 of the sheet (20250)."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Есептелетін өріс","prompt":"goods кестесінде qty = 10, price = 900. SELECT qty * price FROM goods … осы жазба үшін нені береді?","options":["910","90","10900","9000"],"answer":3,"explanation":"* — көбейту: 10 × 900 = 9000.","points":1,"ru":{"title":"Вычисляемое поле","prompt":"В таблице goods qty = 10, price = 900. Что даст SELECT qty * price FROM goods … для этой записи?","options":["910","90","10900","9000"],"explanation":"* — умножение: 10 × 900 = 9000.","notes":"7 минут: два вопроса и итог."},"en":{"title":"Calculated field","prompt":"In goods qty = 10 and price = 900. What does SELECT qty * price FROM goods … give for this record?","options":["910","90","10900","9000"],"explanation":"* multiplies: 10 × 900 = 9000.","notes":"7 minutes: two questions and the wrap-up."},"stage":"check","notes":"7 минут: екі сұрақ және қорытынды."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Деректер қорының түрі","prompt":"Банктің барлық бөлімшесі қосылатын, деректері бір орталықта сақталатын қор қалай аталады?","options":["Жеке","Орталықтандырылған","Қағаз","Уақытша"],"answer":1,"explanation":"Деректері бір орталықта сақталатын қор — орталықтандырылған.","points":1,"ru":{"title":"Вид базы данных","prompt":"Как называется база, к которой подключаются все отделения банка, а данные хранятся в одном центре?","options":["Персональная","Централизованная","Бумажная","Временная"],"explanation":"База с данными в одном центре — централизованная."},"en":{"title":"Type of database","prompt":"What is a database called that all the branches of a bank connect to, with the data kept in one centre?","options":["Personal","Centralized","Paper","Temporary"],"explanation":"A database with its data in one centre is centralized."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s9$::jsonb),
    ($s9$Өзіңді тексер: Деректер қоры$s9$, $s9$Информатика$s9$, 7, $s9${"summary":"2-тарауды қайталау: деректер қоры, жазба, өріс, деректер түрлері, SELECT, WHERE, ORDER BY, GROUP BY, диаграмма түрлері.","objectives":["Тараудың негізгі ұғымдарын түсіндіру","Шарт, сұрыптау және топтау бар сұраныстарды өз бетімен жазу","Өз білімін бағалап, қайталайтын тақырыпты анықтау"],"grade":9,"duration":"45 минут","prior":"2-тараудың барлық сабағын өткен (2.1–2.7).","env":"ClassFlow кестесі және ClassFlow SQL редакторы (браузерде, орнату керек емес). Әр оқушыға бір құрылғы және интернет қажет. Google аккаунты керек емес.","source":"Информатика, 9-сынып оқулығы, 2-тарау, 38 беттер. Сабақ оқулықтан әдейі ауытқиды: Google Forms орнына әр тақырып кестеде және SQL-де қатар орындалады. Барлық сұраныстар мен жауаптар орындалып тексерілген, деректер оқу үшін құрастырылған.","stages":[{"k":"warmup","min":5,"do":"Жазба мен деректер түрі туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Сұраныс бөліктерінің ретін қайталайды"},{"k":"example","min":10,"do":"Мұғаліммен бірге барлық бөлігі бар бір сұранысты талдайды"},{"k":"practice","min":15,"do":"Үш тапсырманы өзі орындайды; үлгерген оқушы ★ сұранысты жазады"},{"k":"check","min":7,"do":"Үш сұрақты тест тапсырып, қай тақырыпты қайталау керегін айтады"}],"ru":{"summary":"Повторение главы 2: база данных, запись, поле, типы данных, SELECT, WHERE, ORDER BY, GROUP BY, виды диаграмм.","objectives":["Объяснять основные понятия главы","Самостоятельно писать запросы с условием, сортировкой и группировкой","Оценивать свои знания и находить тему для повторения"],"prior":"Пройдены все уроки главы 2 (2.1–2.7).","env":"Таблица ClassFlow и SQL-редактор ClassFlow (в браузере, устанавливать ничего не нужно). Каждому ученику нужны устройство и интернет. Аккаунт Google не нужен.","source":"Информатика, учебник 9 класса, глава 2, с. 38. Урок намеренно отходит от учебника: вместо Google Forms каждая тема выполняется параллельно в таблице и в SQL. Все запросы и ответы проверены выполнением, данные учебные.","stages":["Отвечает на два вопроса о записи и типах данных","Повторяет порядок частей запроса","Вместе с учителем разбирает один запрос со всеми частями","Сам выполняет три задания; кто успел — запрос ★","Проходит тест из трёх вопросов и говорит, какую тему надо повторить"]},"en":{"summary":"A review of chapter 2: database, record, field, data types, SELECT, WHERE, ORDER BY, GROUP BY, chart types.","objectives":["Explain the main ideas of the chapter","Write queries with a condition, sorting and grouping without help","Assess your own knowledge and find the topic to revise"],"prior":"All the lessons of chapter 2 are done (2.1–2.7).","env":"The ClassFlow sheet and the ClassFlow SQL editor (in the browser, nothing to install). One device per student and the internet. No Google account is needed.","source":"Informatics, Grade 9 textbook, chapter 2, pp. 38. The lesson leaves the textbook on purpose: instead of Google Forms every topic is done side by side in a sheet and in SQL. Every query and answer was run; the data are made for the classroom.","stages":["Answers two questions about records and data types","Revises the order of the parts of a query","Takes apart one query with every part with the teacher","Does three tasks alone; fast students write the ★ query","Takes a three-question test and says which topic to revise"]}}$s9$::jsonb, $s9$[{"term":"SELECT","definition":"SELECT — кестеден өрістерді таңдап көрсетеді · SELECT — выбирает и показывает поля таблицы · SELECT — picks and shows the fields of a table"},{"term":"WHERE","definition":"WHERE — шартқа сәйкес жазбаларды қалдырады · WHERE — оставляет записи, подходящие под условие · WHERE — keeps the records that meet a condition"},{"term":"ORDER BY","definition":"ORDER BY — нәтижені сұрыптайды · ORDER BY — сортирует результат · ORDER BY — sorts the result"},{"term":"GROUP BY","definition":"GROUP BY — жазбаларды топтайды · GROUP BY — группирует записи · GROUP BY — groups the records"}]$s9$::jsonb, $s9$[{"type":"title","pageType":"slide","templateId":"title","title":"Өзіңді тексер: Деректер қоры","subtitle":"Информатика 9-сынып · 2-тарау «Деректер қоры» · оқулық 38-б.","ru":{"title":"Проверь себя: Базы данных","subtitle":"Информатика 9 класс · глава 2 «Базы данных» · учебник, с. 38"},"en":{"title":"Check yourself: Databases","subtitle":"Informatics Grade 9 · Chapter 2 “Databases” · textbook pp. 38"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Жазба мен өріс","prompt":"books кестесінде 8 жол және 7 баған бар. Онда неше жазба және неше өріс бар?","options":["7 жазба, 8 өріс","8 жазба, 7 өріс","56 жазба","15 өріс"],"answer":1,"explanation":"Жол — жазба, баған — өріс: 8 жазба, 7 өріс.","points":1,"ru":{"title":"Запись и поле","prompt":"В таблице books 8 строк и 7 столбцов. Сколько в ней записей и сколько полей?","options":["7 записей, 8 полей","8 записей, 7 полей","56 записей","15 полей"],"explanation":"Строка — запись, столбец — поле: 8 записей, 7 полей.","notes":"5 минут. Это итоговый урок. Назовите ученикам цель: понять, какую тему они знают хорошо, а какую нужно повторить."},"en":{"title":"Record and field","prompt":"The table books has 8 rows and 7 columns. How many records and how many fields?","options":["7 records, 8 fields","8 records, 7 fields","56 records","15 fields"],"explanation":"A row is a record, a column a field: 8 records, 7 fields.","notes":"5 minutes. This is the closing lesson. Tell the students the aim: to find which topic they know well and which to revise."},"stage":"warmup","notes":"5 минут. Бұл — қорытынды сабақ. Оқушыларға мақсатты айтыңыз: қай тақырыпты жақсы білетінін және қайсысын қайталау керегін анықтау."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Деректер түрі","prompt":"Тауардың атауы (мысалы, «Шай») сақталатын өрістің SQL түрі қандай?","options":["INTEGER","REAL","DATE","TEXT"],"answer":3,"explanation":"Атау — мәтін: TEXT.","points":1,"ru":{"title":"Тип данных","prompt":"Какой тип SQL у поля с названием товара (например, «Шай»)?","options":["INTEGER","REAL","DATE","TEXT"],"explanation":"Название — текст: TEXT."},"en":{"title":"Data type","prompt":"Which SQL type does a field with the name of an item (for example “Шай”) have?","options":["INTEGER","REAL","DATE","TEXT"],"explanation":"A name is text: TEXT."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Сұраныстың бөліктері","bullets":["SELECT өрістер FROM кесте — нені және қайдан көрсету керек.","WHERE шарт — қай жазбаларды қалдыру; GROUP BY өріс — қалай топтау.","ORDER BY өріс — қалай сұрыптау; LIMIT n — неше жол қалдыру. Бөліктер дәл осы ретпен жазылады."],"code":"SELECT … FROM … WHERE … GROUP BY … ORDER BY … LIMIT …;","lang":"text","ru":{"title":"Части запроса","bullets":["SELECT поля FROM таблица — что и откуда показать.","WHERE условие — какие записи оставить; GROUP BY поле — как сгруппировать.","ORDER BY поле — как отсортировать; LIMIT n — сколько строк оставить. Части пишут именно в этом порядке."],"notes":"8 минут. Оставьте порядок на доске. Напомните соответствия в таблице: WHERE ↔ условие COUNTIF, GROUP BY ↔ SUMIF, ORDER BY ↔ сортировка."},"en":{"title":"The parts of a query","bullets":["SELECT fields FROM table: what to show and from where.","WHERE condition: which records to keep; GROUP BY field: how to group.","ORDER BY field: how to sort; LIMIT n: how many rows to keep. The parts are written in exactly this order."],"notes":"8 minutes. Keep the order on the board. Recall the sheet counterparts: WHERE ↔ a COUNTIF condition, GROUP BY ↔ SUMIF, ORDER BY ↔ sorting."},"stage":"together","notes":"8 минут. Ретті тақтада қалдырыңыз. Кестедегі сәйкестіктерді еске түсіріңіз: WHERE ↔ COUNTIF шарты, GROUP BY ↔ SUMIF, ORDER BY ↔ сұрыптау.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: барлық бөлігі бар сұраныс","bullets":["Орындамас бұрын болжа: неше жол шығады және бірінші жолда қай жанр тұрады?","«Орындау» бас та, болжамыңды тексер.","WHERE шартын year > 1950 деп өзгерт: нәтиже қалай өзгерді?"],"code":"SELECT genre, SUM(qty) AS total FROM books WHERE year > 1900 GROUP BY genre ORDER BY total DESC;","lang":"sql","sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"SELECT genre, SUM(qty) AS total FROM books WHERE year > 1900 GROUP BY genre ORDER BY total DESC;"},"notes":"10 минут. 1900 жылдан кейінгі бес кітап: Adventure 17, Classical 14, History 6 — үш жол. year > 1950 болса: Adventure 17, History 6, Classical 4. Алдымен WHERE сүзеді, содан кейін ғана топтау жүреді.","ru":{"title":"Пример: запрос со всеми частями","bullets":["До запуска предскажи: сколько строк выйдет и какой жанр будет в первой строке?","Нажми «Выполнить» и проверь свой прогноз.","Измени условие WHERE на year > 1950: как изменился результат?"],"notes":"10 минут. Пять книг после 1900 года: Adventure 17, Classical 14, History 6 — три строки. При year > 1950: Adventure 17, History 6, Classical 4. Сначала WHERE отбирает, и только потом идёт группировка."},"en":{"title":"Example: a query with every part","bullets":["Before running, predict: how many rows, and which genre is in the first row?","Press “Run” and check your prediction.","Change the WHERE condition to year > 1950: how did the result change?"],"notes":"10 minutes. Five books after 1900: Adventure 17, Classical 14, History 6: three rows. With year > 1950: Adventure 17, History 6, Classical 4. WHERE filters first; grouping comes after."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["46742d11"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","ordered":true,"rows":3},"title":"Тапсырма 1: Classical кітаптары","prompt":"Classical жанрындағы кітаптардың атауы (title) мен жылын (year) ескіден жаңаға қарай көрсет.","notes":"15 минут (төрт тапсырма), оқушылар көмексіз жұмыс істейді. Дұрыс сұраныс: SELECT title, year FROM books WHERE genre = 'Classical' ORDER BY year;","ru":{"title":"Задание 1: книги жанра Classical","prompt":"Покажи название (title) и год (year) книг жанра Classical от самой старой к самой новой.","notes":"15 минут (четыре задания), ученики работают без помощи. Верный запрос: SELECT title, year FROM books WHERE genre = 'Classical' ORDER BY year;"},"en":{"title":"Task 1: the Classical books","prompt":"Show the title and the year of the Classical books from the oldest to the newest.","notes":"15 minutes (four tasks); students work without help. Correct query: SELECT title, year FROM books WHERE genre = 'Classical' ORDER BY year;"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":2,"accept":["9dc6c323"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","rows":3},"title":"Тапсырма 2: рейтинг бойынша сан","prompt":"Әр рейтингте (rating) неше кітап бар? Екі баған: рейтинг және жазбалар саны.","notes":"Дұрыс сұраныс: SELECT rating, COUNT(*) FROM books GROUP BY rating;","ru":{"title":"Задание 2: количество по рейтингу","prompt":"Сколько книг с каждым рейтингом (rating)? Два столбца: рейтинг и число записей.","notes":"Верный запрос: SELECT rating, COUNT(*) FROM books GROUP BY rating;"},"en":{"title":"Task 2: count by rating","prompt":"How many books have each rating? Two columns: the rating and the number of records.","notes":"Correct query: SELECT rating, COUNT(*) FROM books GROUP BY rating;"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Тапсырма 3: жалпы сан","prompt":"Кітапханадағы барлық кітаптың жалпы дана саны қанша? Оны кез келген жолмен тап (мысалы, SELECT SUM(qty) FROM books;) да, санын жаз.","accept":["52"],"points":2,"notes":"10 + 4 + 6 + 8 + 5 + 3 + 7 + 9 = 52.","ru":{"title":"Задание 3: общее количество","prompt":"Сколько всего экземпляров книг в библиотеке? Найди любым способом (например, SELECT SUM(qty) FROM books;) и запиши число.","notes":"10 + 4 + 6 + 8 + 5 + 3 + 7 + 9 = 52."},"en":{"title":"Task 3: the grand total","prompt":"How many copies does the library have in all? Find it any way you like (for example SELECT SUM(qty) FROM books;) and type the number.","notes":"10 + 4 + 6 + 8 + 5 + 3 + 7 + 9 = 52."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"sql","kind":"practice","points":3,"accept":["c83b6323"],"sql":{"setup":"CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT, author TEXT, genre TEXT, year INTEGER, qty INTEGER, rating INTEGER);\nINSERT INTO books VALUES\n  (1, 'Абай жолы', 'Мұхтар Әуезов', 'Classical', 1942, 10, 5),\n  (2, 'Қан мен тер', 'Әбдіжәміл Нұрпейісов', 'Classical', 1970, 4, 4),\n  (3, 'Көшпенділер', 'Ілияс Есенберлин', 'History', 1976, 6, 5),\n  (4, 'Менің атым Қожа', 'Бердібек Соқпақбаев', 'Adventure', 1957, 8, 5),\n  (5, 'Шерлок Холмс', 'Артур Конан Дойл', 'Detective', 1892, 5, 5),\n  (6, 'Соғыс және бейбітшілік', 'Лев Толстой', 'Classical', 1869, 3, 4),\n  (7, 'Алиса ғажайыптар елінде', 'Льюис Кэрролл', 'Adventure', 1865, 7, 4),\n  (8, 'Алхимик', 'Пауло Коэльо', 'Adventure', 1988, 9, 3);","start":"","ordered":true,"rows":3},"title":"★ Күрделі: жаңа кітаптар бойынша есеп","prompt":"Тек 1900 жылдан кейін шыққан кітаптарды ал. Әр жанр үшін жалпы дана санын көрсет, нәтижені сол сан бойынша кему ретімен шығар. Екі баған: жанр және қосынды.","notes":"Жылдам оқушыларға. Мысал слайдындағы сұраныспен бірдей — оқушы оны өзі қайта құрастыруы керек.","ru":{"title":"★ Сложнее: отчёт по новым книгам","prompt":"Возьми только книги, вышедшие после 1900 года. Для каждого жанра покажи общее количество, результат — по убыванию этого числа. Два столбца: жанр и сумма.","notes":"Для быстрых учеников. Тот же запрос, что на слайде с примером: ученик должен собрать его сам."},"en":{"title":"★ Harder: a report on the newer books","prompt":"Take only the books published after 1900. For each genre show the total copies, ordered by that number, descending. Two columns: the genre and the total.","notes":"For fast students. The same query as on the example slide: the student has to rebuild it alone."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Бөліктердің реті","prompt":"Қай сұраныс дұрыс ретпен жазылған?","options":["SELECT title FROM books WHERE qty > 5 ORDER BY qty;","SELECT title WHERE qty > 5 FROM books ORDER BY qty;","FROM books SELECT title ORDER BY qty WHERE qty > 5;","SELECT title FROM books ORDER BY qty WHERE qty > 5;"],"answer":0,"explanation":"Реті: SELECT … FROM … WHERE … ORDER BY …","points":1,"ru":{"title":"Порядок частей","prompt":"Какой запрос записан в правильном порядке?","options":["SELECT title FROM books WHERE qty > 5 ORDER BY qty;","SELECT title WHERE qty > 5 FROM books ORDER BY qty;","FROM books SELECT title ORDER BY qty WHERE qty > 5;","SELECT title FROM books ORDER BY qty WHERE qty > 5;"],"explanation":"Порядок: SELECT … FROM … WHERE … ORDER BY …","notes":"7 минут: три вопроса и итог. В итоге каждый ученик называет одну тему для повторения."},"en":{"title":"The order of the parts","prompt":"Which query is written in the right order?","options":["SELECT title FROM books WHERE qty > 5 ORDER BY qty;","SELECT title WHERE qty > 5 FROM books ORDER BY qty;","FROM books SELECT title ORDER BY qty WHERE qty > 5;","SELECT title FROM books ORDER BY qty WHERE qty > 5;"],"explanation":"The order: SELECT … FROM … WHERE … ORDER BY …","notes":"7 minutes: three questions and the wrap-up. In the wrap-up every student names one topic to revise."},"stage":"check","notes":"7 минут: үш сұрақ және қорытынды. Қорытындыда әр оқушы қайталайтын бір тақырыпты атайды."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Кесте мен SQL","prompt":"Кестедегі =SUMIF(B2:B9;\"History\";D2:D9) формуласына SQL-дегі қай сұраныс сәйкес келеді?","options":["SELECT COUNT(*) FROM books WHERE genre = 'History';","SELECT * FROM books ORDER BY genre;","SELECT SUM(qty) FROM books WHERE genre = 'History';","SELECT MAX(qty) FROM books;"],"answer":2,"explanation":"SUMIF — шартқа сәйкес сандардың қосындысы: SUM … WHERE.","points":1,"ru":{"title":"Таблица и SQL","prompt":"Какой запрос SQL соответствует формуле таблицы =SUMIF(B2:B9;\"History\";D2:D9)?","options":["SELECT COUNT(*) FROM books WHERE genre = 'History';","SELECT * FROM books ORDER BY genre;","SELECT SUM(qty) FROM books WHERE genre = 'History';","SELECT MAX(qty) FROM books;"],"explanation":"SUMIF — сумма чисел по условию: SUM … WHERE."},"en":{"title":"Sheet and SQL","prompt":"Which SQL query matches the sheet formula =SUMIF(B2:B9;\"History\";D2:D9)?","options":["SELECT COUNT(*) FROM books WHERE genre = 'History';","SELECT * FROM books ORDER BY genre;","SELECT SUM(qty) FROM books WHERE genre = 'History';","SELECT MAX(qty) FROM books;"],"explanation":"SUMIF is a conditional total: SUM … WHERE."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Диаграмма түрі","prompt":"Дүкендегі үш санаттың тауар санын өзара салыстыру керек. Қай диаграмма қолайлы?","options":["Сызықтық","Ешқайсысы","Тек мәтін","Бағанды"],"answer":3,"explanation":"Топтарды салыстыру — бағанды диаграмма.","points":1,"ru":{"title":"Вид диаграммы","prompt":"Нужно сравнить количество товаров трёх категорий магазина. Какая диаграмма подходит?","options":["Линейная","Никакая","Только текст","Столбчатая"],"explanation":"Сравнение групп — столбчатая диаграмма."},"en":{"title":"Chart type","prompt":"We must compare the quantities of the three categories of a shop. Which chart fits?","options":["Line","None","Only text","Bar"],"explanation":"Comparing groups calls for a bar chart."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s9$::jsonb)
  ) as t(title, subject, position, plan, terms, slides)
  loop
    select cl.lesson_id into v_lesson from public.cf_curr_lessons cl where cl.module_id = v_module and cl.position = v_spec.position limit 1;
    -- by title only a lesson that sits in no module: a lesson of another module with the same title is somebody else's work and must not be overwritten
    if v_lesson is null then select l.id into v_lesson from public.cf_lessons l where l.school_id = v_school and l.title = v_spec.title and not exists (select 1 from public.cf_curr_lessons x where x.lesson_id = l.id) limit 1; end if;
    if v_lesson is null then
      insert into public.cf_lessons (school_id, owner_id, title, subject, plan, slides, terms)
      values (v_school, v_owner, v_spec.title, v_spec.subject, v_spec.plan, v_spec.slides, v_spec.terms) returning id into v_lesson;
    else
      update public.cf_lessons set title = v_spec.title, subject = v_spec.subject, plan = v_spec.plan, slides = v_spec.slides, terms = v_spec.terms, updated_at = now() where id = v_lesson;
    end if;
    insert into public.cf_curr_lessons (lesson_id, module_id, position) values (v_lesson, v_module, v_spec.position)
    on conflict (lesson_id) do update set module_id = excluded.module_id, position = excluded.position;
    v_lesson := null;
  end loop;
end;
$informatics9$;
